// Home PV Control users.
// Blueprint-compatible multi-inverter version with Main and Settings dashboard layout.
// HBC remains untouched except optional selection of input_select.house_battery_strategy.

const haStates = global.get('homeassistant.homeAssistant.states') || {};

function states() {
    return haStates;
}

function getState(entity, fallback = undefined) {
    const s = states();
    if (!entity || !s[entity]) return fallback;
    return s[entity].state;
}

function numEntity(entity, fallback = 0) {
    const v = parseFloat(getState(entity, fallback));
    return Number.isFinite(v) ? v : fallback;
}

function strEntity(entity, fallback = '') {
    const v = getState(entity, fallback);
    return v === undefined || v === null ? fallback : String(v);
}

// Settings helper wrappers. Kept separate from numEntity()/strEntity() for readability
// and future helper-specific validation.
function helperNum(entity, fallback = 0) {
    return numEntity(entity, fallback);
}

function helperStr(entity, fallback = '') {
    return strEntity(entity, fallback);
}

function clamp(v, min, max) {
    return Math.min(Math.max(v, min), max);
}


function inverterWriteRequired(currentValue, targetValue, thresholdWatts = 5) {
    if (!Number.isFinite(currentValue) || !Number.isFinite(targetValue)) return false;
    return Math.abs(targetValue - currentValue) >= thresholdWatts;
}


function distributeIncreaseTargets(inverters, totalIncrease, deadband) {
    const desiredIncrease = Math.round(Math.max(0, totalIncrease));
    const targets = inverters.map(inv => ({
        name: inv.name,
        entity: inv.limit_entity,
        current: inv.current,
        target: inv.current,
        full_power: inv.full_power,
        minimum_power: inv.minimum_power,
        changed: false
    }));

    if (desiredIncrease <= 0 || targets.length === 0) return targets;

    const capacity = targets.map(t => Math.max(0, t.full_power - t.current));
    const maxIncrease = Math.round(capacity.reduce((s, v) => s + v, 0));
    const targetIncrease = Math.min(desiredIncrease, maxIncrease);

    // Deadband is applied to the total reveal decision, not to each inverter share.
    // Once the total requested reveal is meaningful, keep proportional distribution
    // across all limited inverters. Only suppress very tiny per-inverter writes.
    if (targetIncrease <= deadband) return targets;

    let deltas = targets.map(() => 0);
    let remaining = targetIncrease;

    // First pass: distribute proportionally by inverter size while respecting remaining headroom.
    for (let guard = 0; guard < 10 && remaining > 0.5; guard++) {
        const active = targets
            .map((t, i) => ({ i, weight: t.full_power, cap: Math.max(0, capacity[i] - deltas[i]) }))
            .filter(x => x.cap > 0.5);
        if (active.length === 0) break;

        const weightTotal = active.reduce((s, x) => s + x.weight, 0);
        let allocated = 0;
        for (const x of active) {
            const add = Math.min(x.cap, remaining * (x.weight / weightTotal));
            deltas[x.i] += add;
            allocated += add;
        }
        if (allocated <= 0.5) break;
        remaining -= allocated;
    }

    // Round to whole watts and correct rounding drift so the requested total step is preserved.
    deltas = deltas.map((d, i) => Math.min(capacity[i], Math.round(d)));
    let diff = targetIncrease - deltas.reduce((s, d) => s + d, 0);
    for (let guard = 0; diff !== 0 && guard < 100; guard++) {
        if (diff > 0) {
            let best = -1;
            let bestCap = 0;
            for (let i = 0; i < deltas.length; i++) {
                const capLeft = capacity[i] - deltas[i];
                if (capLeft > bestCap) {
                    bestCap = capLeft;
                    best = i;
                }
            }
            if (best < 0 || bestCap <= 0) break;
            deltas[best] += 1;
            diff -= 1;
        } else {
            let best = -1;
            let bestDelta = 0;
            for (let i = 0; i < deltas.length; i++) {
                if (deltas[i] > bestDelta) {
                    bestDelta = deltas[i];
                    best = i;
                }
            }
            if (best < 0 || bestDelta <= 0) break;
            deltas[best] -= 1;
            diff += 1;
        }
    }

    return targets.map((t, i) => {
        const target = Math.round(clamp(t.current + deltas[i], t.minimum_power, t.full_power));
        return {
            ...t,
            target,
            changed: target !== t.current
        };
    });
}

function serviceMsg(domain, service, data, target) {
    return { payload: { action: `${domain}.${service}`, data, target } };
}

function validEntity(entity) {
    return typeof entity === 'string' && entity.includes('.');
}

function entityExists(entity) {
    if (!validEntity(entity)) return false;
    const s = states();
    if (!s[entity]) return false;
    const st = String(s[entity].state || '').trim().toLowerCase();
    return !['unknown', 'unavailable', 'none', ''].includes(st);
}

function stateIsNumeric(entity) {
    const st = states()[entity] && states()[entity].state;
    if (st === undefined || st === null) return false;
    const text = String(st).trim().toLowerCase();
    if (['unknown', 'unavailable', 'none', ''].includes(text)) return false;
    return Number.isFinite(parseFloat(text));
}

function entityTimestampMs(entity) {
    const item = states()[entity];
    if (!item) return 0;
    const parsed = Date.parse(item.last_changed || item.last_updated);
    return Number.isFinite(parsed) ? parsed : 0;
}

function entityAgeMs(entity, referenceNow = Date.now()) {
    const timestamp = entityTimestampMs(entity);
    return timestamp > 0 ? Math.max(0, referenceNow - timestamp) : Infinity;
}

function pickedEntity(textEntity, fallback = '') {
    // Entity IDs are configured with input_text helpers. This avoids huge
    // dynamic dropdown option arrays on large Home Assistant installations.
    const typed = helperStr(textEntity, '').trim();
    if (validEntity(typed) && typed !== 'select_entity_first') return typed;
    return validEntity(fallback) ? fallback : '';
}


// Persistent-notification display helper only. Control calculations and other outputs keep raw values.
function formatNotificationPrice(value) {
    const number = Number(value);
    return Number.isFinite(number) ? number.toFixed(3) : 'unknown';
}

function insightTime() {
    const d = new Date();
    const hh = String(d.getHours()).padStart(2, '0');
    const mm = String(d.getMinutes()).padStart(2, '0');
    const ss = String(d.getSeconds()).padStart(2, '0');
    return `${hh}:${mm}:${ss}`;
}

function insight(source, node, message) {
    const body = `${source} | ${node} | ${message}`;
    const line = `${insightTime()} | ${body}`;
    const key = body.trim();
    // Deduplicate inside one EMS run as well as against stored history.
    if (!newInsights.some(item => item.key === key)) {
        newInsights.push({ line, key });
    }
}


const now = Date.now();
const enabled = strEntity('input_boolean.hpvc_enabled', 'on') === 'on';
const notify = strEntity('input_boolean.hpvc_notifications', 'on') === 'on';
const settingsVisible = strEntity('input_boolean.hpvc_config', 'off') === 'on';
const hbcControlRequested = strEntity('input_boolean.hpvc_control_hbc_strategy', 'off') === 'on';
const defaultsRestoredEventState = strEntity('input_button.hpvc_defaults_restored_event', '');

// Configurable entity IDs
const gridEntity = pickedEntity('input_text.hpvc_grid_power_sensor', '');
const marketEntity = pickedEntity('input_text.hpvc_market_price_sensor', '');
const allInEntity = pickedEntity('input_text.hpvc_all_in_price_sensor', '');
const pvPowerEntity = pickedEntity('input_text.hpvc_pv_power_sensor', '');
const hbcStrategyEntity = pickedEntity('input_text.hpvc_battery_strategy_entity', 'input_select.house_battery_strategy');
const hasHbc = entityExists(hbcStrategyEntity);

// Live values
const market = numEntity(marketEntity, 999);
const allIn = numEntity(allInEntity, 999);
const grid = numEntity(gridEntity, 0);        // negative export, positive import
const pvPower = numEntity(pvPowerEntity, 0);


// Settings
const limitingPrice = helperNum('input_number.hpvc_pv_limiting_price', 0.00);
const chargePrice = helperNum('input_number.hpvc_battery_charge_price', 0.10);
const expensivePrice = helperNum('input_number.hpvc_battery_expensive_price', 0.35);
const hysteresis = helperNum('input_number.hpvc_battery_price_hysteresis', 0.02);
const pvRestorePrice = limitingPrice + Math.max(0, hysteresis);

const exportStart = helperNum('input_number.hpvc_export_start_threshold', -150);
const exportTarget = helperNum('input_number.hpvc_export_stop_threshold', -25);
const importRecalc = helperNum('input_number.hpvc_import_restore_threshold', 150);
const thresholdConfigurationValid = exportStart < exportTarget && exportTarget <= 0 && importRecalc >= 0;
const thresholdConfigurationError = thresholdConfigurationValid
    ? ''
    : `Invalid power thresholds: require Export Start < Target Export <= 0 W and Import Restore >= 0 W (current: ${exportStart} W, ${exportTarget} W, ${importRecalc} W)`;
const adaptiveRevealCapWatts = 800;
const minPvPower = helperNum('input_number.hpvc_pv_min_power_for_control', 100);
const nightRestorePower = helperNum('input_number.hpvc_pv_night_restore_power', 10);
const cooldownSeconds = helperNum('input_number.hpvc_cooldown_seconds', 60);
const deadband = helperNum('input_number.hpvc_pv_adjust_deadband', 25);
const nightRestorePersistenceMs = 120000;
const sunEntity = 'sun.sun';
const sunAvailable = entityExists(sunEntity);
const sunState = strEntity(sunEntity, 'unavailable').trim().toLowerCase();
const sunBelowHorizon = sunAvailable && sunState === 'below_horizon';
const fallbackNightLowPv = !sunAvailable && pvPower < nightRestorePower;
const nightRestoreCondition = sunAvailable ? sunBelowHorizon : fallbackNightLowPv;
const nightRestoreSinceStored = Number(flow.get('homePvControlNightRestoreSince'));
let nightRestoreSince = Number.isFinite(nightRestoreSinceStored) ? nightRestoreSinceStored : 0;
// Prefer astronomical sunset. Only use the configurable PV threshold when sun.sun is unavailable.
// Both paths must remain true continuously for 120 seconds before full inverter limits are restored.
if (nightRestoreCondition) {
    if (!nightRestoreSince) nightRestoreSince = now;
} else {
    nightRestoreSince = 0;
}
flow.set('homePvControlNightRestoreSince', nightRestoreSince);
// Clear the former context key from pre-v1.3.0 development builds so stale data cannot influence diagnostics.
flow.set('homePvControlLowPvSince', 0);
const persistentNightRestore = nightRestoreSince > 0 && (now - nightRestoreSince) >= nightRestorePersistenceMs;

const configuredChargeStrategy = strEntity('input_select.hpvc_charge_strategy', 'Charge');
const configuredBalancedStrategy = strEntity('input_select.hpvc_balanced_strategy', 'Dynamic');
const configuredExpensiveStrategy = strEntity('input_select.hpvc_expensive_strategy', 'Dynamic');
const currentStrategy = strEntity(hbcStrategyEntity, 'unknown');
const hbcStrategyOptions = Array.isArray(haStates[hbcStrategyEntity]?.attributes?.options)
    ? haStates[hbcStrategyEntity].attributes.options.map(String)
    : [];
const hbcStrategyControlAvailable = hasHbc && hbcStrategyOptions.length > 0;
const controlHbc = hbcControlRequested && hbcStrategyControlAvailable;

function resolveHbcStrategy(configured, preferred) {
    if (hbcStrategyOptions.includes(configured)) return configured;
    if (hbcStrategyOptions.includes(preferred)) return preferred;
    if (hbcStrategyOptions.includes(currentStrategy)) return currentStrategy;
    return hbcStrategyOptions.length > 0 ? hbcStrategyOptions[0] : '';
}

// The Charge zone is automatically managed. Always use the exact HBC
// `Charge` option when it exists; only use a valid fallback when HBC removes it.
const chargeStrategy = hbcStrategyOptions.includes('Charge')
    ? 'Charge'
    : resolveHbcStrategy(configuredChargeStrategy, 'Charge');
const balancedStrategy = resolveHbcStrategy(configuredBalancedStrategy, 'Dynamic');
const expensiveStrategy = resolveHbcStrategy(configuredExpensiveStrategy, 'Dynamic');


function hbcBatteryPowerEntity(index) {
    return `sensor.marstek_m${index}_ac_power`;
}

function hbcBatteryMaxChargePowerEntity(index) {
    return `number.marstek_m${index}_max_charge_power`;
}

function hbcBatterySocEntity(index) {
    return `sensor.marstek_m${index}_battery_state_of_charge`;
}

    let rememberedMaxChargePowers = flow.get('homePvControlBatteryMaxChargePowers');
    if (!rememberedMaxChargePowers || typeof rememberedMaxChargePowers !== 'object') {
        rememberedMaxChargePowers = {};
    }

function hbcBatteryPowerSummary(count, revealStepFallback = 0, controlDeadband = 25) {
    let total = 0;
    let charging = false;
    let chargeHeadroom = false;
    let atMaxChargePower = false;
    let availableChargePower = 0;
    let highestSoc = null;
    let lowestSoc = null;
    let chargingSoc = null;
    let chargePriorityHeadroom = false;
    let highSocHeadroom = false;
    let headroomBelow90 = false;
    let headroomFrom90To95 = false;
    let headroomAtOrAbove95 = false;
    let fullBatteryCount = 0;
    let socKnownCount = 0;
    let socUnknownCount = 0;
    let usableBatteryCount = 0;
    let unavailableBatteryCount = 0;
    let anyBatteryBelow90 = false;
    const batteries = [];

    // Internal safety values only; no new Home Assistant entities.
    const maxChargeMargin = 0.95;
    const usefulFullPvHeadroomWatts = Math.max(200, Math.round(controlDeadband * 4));
    const telemetryTimeoutMs = 120000;

    function socRevealProbeAllowance(soc, maxChargePower) {
        if (!Number.isFinite(soc) || !Number.isFinite(maxChargePower) || maxChargePower <= 0) {
            return 0;
        }
        if (soc >= 100) return 0;

        // Below 90%, raw charger headroom remains available to the global adaptive cap.
        // From 90% onward, probe in progressively smaller SOC-based steps. The battery's
        // measured response guard decides whether another reveal may follow.
        let probeCap = maxChargePower;
        if (soc >= 99) probeCap = 25;
        else if (soc >= 97) probeCap = 50;
        else if (soc >= 95) probeCap = 100;
        else if (soc >= 90) probeCap = 200;

        return Math.max(0, Math.min(maxChargePower, Math.round(probeCap)));
    }

    let socBands = flow.get('homePvControlBatterySocBands');
    if (!socBands || typeof socBands !== 'object') socBands = {};

    for (let i = 1; i <= count; i++) {
        const socEntity = hbcBatterySocEntity(i);
        const powerEntity = hbcBatteryPowerEntity(i);
        const maxEntity = hbcBatteryMaxChargePowerEntity(i);

        const socNumeric = stateIsNumeric(socEntity);
        const powerNumeric = stateIsNumeric(powerEntity);
        const socAgeMs = entityAgeMs(socEntity, now);
        const powerAgeMs = entityAgeMs(powerEntity, now);
        const socFresh = socNumeric && socAgeMs <= telemetryTimeoutMs;
        const powerFresh = powerNumeric && powerAgeMs <= telemetryTimeoutMs;

        // Numeric battery values remain valid operating telemetry even when the
        // value has not changed for several minutes. Home Assistant timestamps
        // describe value updates, not device connectivity. Fresh timestamps are
        // used separately by the post-reveal response guard.
        const telemetryFresh = powerNumeric;
        const batterySoc = socNumeric ? numEntity(socEntity, 0) : null;

        const previousBand = socBands[i] && typeof socBands[i] === 'object' ? socBands[i] : {};
        let high90 = previousBand.high90 === true;
        let high95 = previousBand.high95 === true;
        if (batterySoc !== null) {
            high90 = high90 ? batterySoc >= 89 : batterySoc >= 90;
            high95 = high95 ? batterySoc >= 94 : batterySoc >= 95;
            socBands[i] = { high90, high95 };
            socKnownCount++;
            if (!high90) anyBatteryBelow90 = true;
            highestSoc = highestSoc === null ? batterySoc : Math.max(highestSoc, batterySoc);
            lowestSoc = lowestSoc === null ? batterySoc : Math.min(lowestSoc, batterySoc);
            if (batterySoc >= 99.5) fullBatteryCount++;
        } else {
            socUnknownCount++;
        }

        const info = {
            index: i, soc: batterySoc, socKnown: batterySoc !== null,
            socFresh, powerFresh, telemetryFresh, usable: false,
            socAgeSeconds: Number.isFinite(socAgeMs) ? Math.round(socAgeMs / 1000) : null,
            powerAgeSeconds: Number.isFinite(powerAgeMs) ? Math.round(powerAgeMs / 1000) : null,
            status: 'unavailable', charging: false,
            power: powerNumeric ? numEntity(powerEntity, 0) : null,
            powerTimestampMs: entityTimestampMs(powerEntity),
            maxChargeKnown: false, maxChargePower: 0,
            rawHeadroom: 0, headroom: 0, adaptiveHeadroom: 0,
            taperCap: 0, taperLimited: false, nearMaxCharge: false,
            fullPvHeadroom: false, high90, high95, excludedReason: ''
        };

        if (!powerNumeric) {
            unavailableBatteryCount++;
            info.excludedReason = 'power unavailable';
            batteries.push(info);
            continue;
        }
        if (!socNumeric) {
            unavailableBatteryCount++;
            info.excludedReason = 'SOC unavailable';
            batteries.push(info);
            continue;
        }

        usableBatteryCount++;
        info.usable = true;
        const power = info.power;
        total += power;

        // Read and remember the configured maximum before status-based exits.
        // Idle, full, and discharging batteries remain ineligible for reveal,
        // but the report should still show their known maximum charge power.
        const liveMaxChargePower = stateIsNumeric(maxEntity)
            ? Math.abs(numEntity(maxEntity, 0))
            : 0;
        if (liveMaxChargePower > 0) {
            rememberedMaxChargePowers[i] = liveMaxChargePower;
        }
        const maxChargePower = liveMaxChargePower > 0
            ? liveMaxChargePower
            : Number(rememberedMaxChargePowers[i] || 0);
        if (Number.isFinite(maxChargePower) && maxChargePower > 0) {
            info.maxChargeKnown = true;
            info.maxChargePower = maxChargePower;
        }

        if (batterySoc >= 99.5) {
            info.status = 'full';
            info.excludedReason = 'battery full';
            batteries.push(info);
            continue;
        }
        if (power >= 25) {
            info.status = 'discharging';
            info.excludedReason = 'battery discharging';
            batteries.push(info);
            continue;
        }
        if (power >= 0) {
            info.status = 'idle';

            // An idle battery may be idle only because PV is still limited. Allow it
            // to bootstrap Hidden PV Reveal with the same SOC-based probe ceiling used
            // for charging batteries. The inverter deadband is still applied later to
            // the total reveal request, so probes at or below the deadband are suppressed.
            if (Number.isFinite(maxChargePower) && maxChargePower > 0) {
                const rawHeadroom = Math.max(0, maxChargePower - Math.abs(power));
                const probeAllowance = Math.min(
                    rawHeadroom,
                    socRevealProbeAllowance(batterySoc, maxChargePower)
                );
                info.rawHeadroom = rawHeadroom;
                info.taperCap = probeAllowance;
                info.taperLimited = probeAllowance < rawHeadroom;
                info.headroom = probeAllowance;
                info.adaptiveHeadroom = probeAllowance;

                if (probeAllowance > 0) {
                    chargeHeadroom = true;
                    availableChargePower += probeAllowance;
                    info.status = batterySoc >= 90 ? 'idle (high-SOC probe eligible)' : 'idle (probe eligible)';
                    info.excludedReason = batterySoc >= 90
                        ? `idle; first reveal probe capped at ${Math.round(probeAllowance)} W by SOC and still subject to deadband`
                        : `idle; eligible for an SOC-capped first reveal probe and still subject to deadband`;

                    if (!high90) {
                        headroomBelow90 = true;
                    } else {
                        highSocHeadroom = true;
                        if (high95) headroomAtOrAbove95 = true;
                        else headroomFrom90To95 = true;
                    }
                } else {
                    info.excludedReason = 'battery idle; no probe allowance';
                }
            } else {
                info.excludedReason = 'battery idle; max charge unknown';
            }
            batteries.push(info);
            continue;
        }

        charging = true;
        info.charging = true;
        info.status = 'charging';

        if (Number.isFinite(maxChargePower) && maxChargePower > 0) {
            const rawHeadroom = Math.max(0, maxChargePower - Math.abs(power));
            const nearMaxCharge = Math.abs(power) >= maxChargePower * maxChargeMargin;
            let usableHeadroom = rawHeadroom;
            info.maxChargeKnown = true;
            info.maxChargePower = maxChargePower;
            info.rawHeadroom = rawHeadroom;
            info.nearMaxCharge = nearMaxCharge;

            if (batterySoc < 100) {
                info.taperCap = socRevealProbeAllowance(
                    batterySoc,
                    maxChargePower
                );
                usableHeadroom = Math.min(usableHeadroom, info.taperCap);
                info.taperLimited = usableHeadroom < rawHeadroom;
                if (batterySoc >= 90) {
                    info.status = 'charging (high SOC)';
                    if (info.taperLimited) {
                        info.excludedReason = `high SOC; reveal probes capped at ${Math.round(info.taperCap)} W and repeated only after a safe battery/grid response`;
                    }
                }
            }
            info.headroom = usableHeadroom;

            if (nearMaxCharge || usableHeadroom <= 0) {
                atMaxChargePower = true;
            } else {
                availableChargePower += usableHeadroom;
                chargeHeadroom = true;
                info.adaptiveHeadroom = usableHeadroom;
                if (!high90) {
                    headroomBelow90 = true;
                    if (usableHeadroom >= usefulFullPvHeadroomWatts) {
                        chargePriorityHeadroom = true;
                        info.fullPvHeadroom = true;
                    }
                } else {
                    highSocHeadroom = true;
                    if (high95) headroomAtOrAbove95 = true;
                    else headroomFrom90To95 = true;
                }
                chargingSoc = chargingSoc === null ? batterySoc : Math.min(chargingSoc, batterySoc);
            }
        } else {
            info.status = batterySoc >= 90 && batterySoc < 100 ? 'charging (high SOC)' : 'charging';
            info.excludedReason = 'max charge unknown; battery excluded';
            info.headroom = 0;
            info.adaptiveHeadroom = 0;
        }
        batteries.push(info);
    }

    flow.set('homePvControlBatterySocBands', socBands);
    flow.set('homePvControlBatteryMaxChargePowers', rememberedMaxChargePowers);
    const result = {
        total, charging, chargeHeadroom, availableChargePower,
        atMaxChargePower: charging && !chargeHeadroom && atMaxChargePower,
        highestSoc, lowestSoc, chargingSoc, chargePriorityHeadroom,
        highSocHeadroom, headroomBelow90, headroomFrom90To95,
        headroomAtOrAbove95, socKnownCount, socUnknownCount,
        usableBatteryCount, unavailableBatteryCount,
        anyBatteryBelow90, batteries, usefulFullPvHeadroomWatts,
        telemetryTimeoutMs, batteryFull: count > 0 && fullBatteryCount >= count
    };

    flow.set('homePvControlBatteryDiagnostics', {
        ts: now,
        totalAvailableHeadroom: Math.round(availableChargePower),
        usableBatteryCount, unavailableBatteryCount,
        batteries: batteries.map(b => ({
            index: b.index, status: b.status, soc: b.soc, power: b.power,
            maxChargeKnown: b.maxChargeKnown,
            maxChargePower: Math.round(b.maxChargePower || 0),
            rawHeadroom: Math.round(b.rawHeadroom || 0),
            usableHeadroom: Math.round(b.adaptiveHeadroom || 0),
            taperLimited: b.taperLimited === true,
            telemetryFresh: b.telemetryFresh === true,
            powerFresh: b.powerFresh === true,
            powerTimestampMs: Number(b.powerTimestampMs || 0),
            socAgeSeconds: b.socAgeSeconds, powerAgeSeconds: b.powerAgeSeconds,
            excludedReason: b.excludedReason || ''
        }))
    });
    return result;
}

// Inverter configuration from blueprint-compatible helpers.
// User selects inverter count (1-10). Only the first N slots are used.
const inverterCount = Math.round(clamp(helperNum('input_number.hpvc_inverter_count', 1), 1, 10));
const configuredInverters = [];
for (let i = 1; i <= inverterCount; i++) {
    configuredInverters.push({
        name: `PV${i}`,
        limit_entity: pickedEntity(`input_text.hpvc_pv${i}_limit_number`, ''),
        full_power: helperNum(`input_number.hpvc_pv${i}_full_limit`, 0),
        minimum_power: helperNum(`input_number.hpvc_pv${i}_low_limit`, 0)
    });
}

const validConfiguredInverters = configuredInverters
    .filter(inv =>
        validEntity(inv.limit_entity) &&
        inv.full_power > 0 &&
        inv.minimum_power >= 0 &&
        inv.minimum_power < inv.full_power
    )
    .map(inv => ({
        ...inv,
        available: stateIsNumeric(inv.limit_entity),
        current: stateIsNumeric(inv.limit_entity) ? numEntity(inv.limit_entity, NaN) : null
    }));

const unavailableInverters = validConfiguredInverters.filter(inv => !inv.available);
let inverters = validConfiguredInverters.filter(inv => inv.available);

const outputs = Array(9).fill(null);

// Append one or more messages to a Node-RED output without creating nested arrays.
// A single message remains an object; multiple messages become one flat array.
function appendOutputMessage(index, message) {
    if (!message) return;
    if (outputs[index] === null) {
        outputs[index] = message;
    } else if (Array.isArray(outputs[index])) {
        outputs[index].push(message);
    } else {
        outputs[index] = [outputs[index], message];
    }
}
// outputs:
// 0 generic inverter limit calls, 1 status, 2 reason, 3 last action,
// 4 targets json, 5 notification, 6 HBC strategy, 7 rolling insights, 8 force HBC toggle off

let status = 'Idle';
let reason = 'No action';
let pvAction = 'none';
let batteryOption = null;
let notification = null;
let notificationCalls = [];
// A new inverter write is queued here and stored only after the previous
// pending write has had a chance to be verified during this evaluation.
