// Detect whether HBC forecast values match the configured market or all-in price.
// The HBC source itself is never changed; this is used only for graph diagnostics.
function hbcForecastCurrentPrice() {
    const item = states()['sensor.hbc_energy_prices_data'];
    const attrs = item && item.attributes ? item.attributes : {};
    const referenceNow = Date.now();
    const pointsPerHour = Number(attrs.datapoints_per_hour);
    const fallbackIntervalMs = Number.isFinite(pointsPerHour) && pointsPerHour > 0
        ? 60 * 60 * 1000 / pointsPerHour
        : 15 * 60 * 1000;
    const valueOf = entry => {
        if (typeof entry === 'number') return entry;
        if (!entry || typeof entry !== 'object') return Number(entry);
        return Number(entry.price ?? entry.value ?? entry.total ?? entry.per_kwh ?? entry.electricity_price);
    };
    const timeOf = entry => entry && (entry.start ?? entry.time ?? entry.from ?? entry.start_time ?? entry.datetime);
    const explicitEndOf = entry => entry && (entry.end ?? entry.to ?? entry.end_time);
    const normalize = value => {
        const raw = Number(value);
        return Number.isFinite(raw) ? raw / 100 : NaN;
    };
    const timestamped = source => {
        const sorted = source
            .filter(entry => entry && timeOf(entry) != null)
            .map(entry => ({
                entry,
                start: Date.parse(timeOf(entry)),
                explicitEnd: Date.parse(explicitEndOf(entry))
            }))
            .filter(item =>
                Number.isFinite(item.start) &&
                Number.isFinite(valueOf(item.entry))
            )
            .sort((a, b) => a.start - b.start);
        return sorted.map((item, index) => {
            const nextStart = sorted[index + 1] && sorted[index + 1].start;
            const end = Number.isFinite(item.explicitEnd) && item.explicitEnd > item.start
                ? item.explicitEnd
                : (Number.isFinite(nextStart) && nextStart > item.start
                    ? nextStart
                    : item.start + fallbackIntervalMs);
            return { ...item, end };
        });
    };

    if (Array.isArray(attrs.marks)) {
        for (const item of timestamped(attrs.marks)) {
            if (referenceNow >= item.start && referenceNow < item.end) {
                return normalize(valueOf(item.entry));
            }
        }
    }

    if (Array.isArray(attrs.prices) && attrs.prices.length) {
        const start = Date.parse(attrs.start);
        if (Number.isFinite(start) && fallbackIntervalMs > 0) {
            const index = Math.floor((referenceNow - start) / fallbackIntervalMs);
            if (index >= 0 && index < attrs.prices.length) {
                const price = normalize(valueOf(attrs.prices[index]));
                if (Number.isFinite(price)) return price;
            }
        }
    }

    const combined = [
        ...(Array.isArray(attrs.today) ? attrs.today : []),
        ...(Array.isArray(attrs.tomorrow) ? attrs.tomorrow : []),
        ...(Array.isArray(attrs.forecast) ? attrs.forecast : [])
    ];
    for (const item of timestamped(combined)) {
        if (referenceNow >= item.start && referenceNow < item.end) {
            return normalize(valueOf(item.entry));
        }
    }
    return NaN;
}

const hbcCurrentForecastPrice = hbcForecastCurrentPrice();

// Learn an approximate all-in formula from the configured Market and All-in sensors.
// No user settings are required. Changed, time-aligned price pairs are retained in
// flow context and fitted as: estimated all-in = market × slope + intercept.
function updateHbcAllInModel() {
    const previous = flow.get('homePvControlHbcAllInModel') || {};

    let storedModel = {};
    try {
        storedModel = JSON.parse(strEntity('input_text.hpvc_hbc_price_model_json', '{}')) || {};
    } catch (error) {
        storedModel = {};
    }

    let storedProgress = {};
    try {
        storedProgress = JSON.parse(strEntity('input_text.hpvc_hbc_price_learning_json', '{}')) || {};
    } catch (error) {
        storedProgress = {};
    }

    // Exact ownership helpers keep the saved model tied to the complete
    // configured Market and All-in entity IDs, including unusually long IDs.
    const storedMarketEntity = strEntity('input_text.hpvc_hbc_price_model_market_entity', '');
    const storedAllInEntity = strEntity('input_text.hpvc_hbc_price_model_all_in_entity', '');
    const storedEntitiesMatch =
        storedMarketEntity === marketEntity &&
        storedAllInEntity === allInEntity;
    const storedReady = storedEntitiesMatch && storedModel.r === true &&
        Number.isFinite(Number(storedModel.a)) && Number.isFinite(Number(storedModel.b)) &&
        Number(storedModel.a) >= 0.5 && Number(storedModel.a) <= 2.0 &&
        Number(storedModel.b) >= -0.25 && Number(storedModel.b) <= 1.0;

    // The compact progress helper stores prices as integer ten-thousandths of
    // €/kWh so initial learning and monthly validation can survive a normal
    // memory-only Node-RED restart without requiring file-backed context.
    const decodePair = pair => Array.isArray(pair) && pair.length >= 2 &&
        Number.isFinite(Number(pair[0])) && Number.isFinite(Number(pair[1]))
        ? { x: Number(pair[0]) / 10000, y: Number(pair[1]) / 10000 }
        : null;
    const decodePairs = list => (Array.isArray(list) ? list : [])
        .map(decodePair)
        .filter(Boolean);
    const storedProgressMatches = storedEntitiesMatch &&
        (storedProgress.t === 'l' || storedProgress.t === 'v');

    const sameEntities = previous.market_entity === marketEntity && previous.all_in_entity === allInEntity;
    let ready = sameEntities && previous.ready === true ? true : storedReady;
    let slope = sameEntities && Number.isFinite(Number(previous.slope))
        ? Number(previous.slope)
        : (storedReady ? Number(storedModel.a) : 1);
    let intercept = sameEntities && Number.isFinite(Number(previous.intercept))
        ? Number(previous.intercept)
        : (storedReady ? Number(storedModel.b) : (Number.isFinite(allIn - market) ? allIn - market : 0));
    const restoredLow = storedProgressMatches && storedProgress.t === 'l'
        ? decodePairs(storedProgress.l).slice(0, 4)
        : [];
    const restoredHigh = storedProgressMatches && storedProgress.t === 'l'
        ? decodePairs(storedProgress.h).slice(-4)
        : [];
    const restoredLast = storedProgressMatches && storedProgress.t === 'l'
        ? decodePair(storedProgress.p)
        : null;
    // The saved low/high observations are already distinct Market-price points.
    // Restore them directly so learning can resume after a restart. The separately
    // saved last pair is used only for change detection, never as a fit sample.
    const restoredTraining = [...restoredLow, ...restoredHigh]
        .map(sample => ({ ...sample, ts: Number(storedProgress.s || now) }));
    let lastObservedPair = sameEntities && previous.last_observed_pair
        ? previous.last_observed_pair
        : restoredLast;
    let samples = sameEntities && Array.isArray(previous.samples)
        ? previous.samples.slice(-96)
        : (!storedReady ? restoredTraining : []);
    let collectionStarted = sameEntities && Number(previous.collection_started) > 0
        ? Number(previous.collection_started)
        : (storedProgressMatches && storedProgress.t === 'l' && Number(storedProgress.s) > 0
            ? Number(storedProgress.s)
            : (samples.length > 0 ? Number(samples[0].ts || now) : 0));
    let learnedAt = sameEntities && Number(previous.learned_at) > 0
        ? Number(previous.learned_at)
        : (Number(storedModel.u) > 0 ? Number(storedModel.u) : 0);
    let lastValidated = sameEntities && Number(previous.last_validated) > 0
        ? Number(previous.last_validated)
        : (Number(storedModel.v) > 0 ? Number(storedModel.v) : (learnedAt || now));
    let validationError = sameEntities && Number.isFinite(Number(previous.validation_error))
        ? Number(previous.validation_error)
        : (Number.isFinite(Number(storedModel.e)) ? Number(storedModel.e) : NaN);
    let validationSamples = sameEntities && Array.isArray(previous.validation_samples)
        ? previous.validation_samples.slice(-3)
        : (storedProgressMatches && storedProgress.t === 'v'
            ? decodePairs(storedProgress.q).slice(-3).map(sample => ({
                ...sample,
                error: Math.abs((sample.x * slope + intercept) - sample.y),
                ts: Number(storedProgress.s || now)
            }))
            : []);
    let count = sameEntities && Number(previous.count) > 0
        ? Number(previous.count)
        : (storedProgressMatches && storedProgress.t === 'l' && Number(storedProgress.n) > 0
            ? Number(storedProgress.n)
            : (Number(storedModel.n) > 0 ? Number(storedModel.n) : samples.length));
    let marketRange = sameEntities && Number.isFinite(Number(previous.range))
        ? Number(previous.range)
        : (samples.length > 1
            ? Math.max(...samples.map(sample => sample.x)) - Math.min(...samples.map(sample => sample.x))
            : 0);
    let relearning = sameEntities && previous.relearning === true;

    const marketTimestamp = entityTimestampMs(marketEntity);
    const allInTimestamp = entityTimestampMs(allInEntity);
    const timestampsAligned = marketTimestamp > 0 && allInTimestamp > 0 &&
        Math.abs(marketTimestamp - allInTimestamp) <= 2 * 60 * 1000;
    const valuesFresh = entityAgeMs(marketEntity, now) <= 30 * 60 * 1000 &&
        entityAgeMs(allInEntity, now) <= 30 * 60 * 1000;
    const pairValid = stateIsNumeric(marketEntity) && stateIsNumeric(allInEntity) &&
        Number.isFinite(market) && Number.isFinite(allIn) && allIn >= market &&
        timestampsAligned && valuesFresh;

    // Once learned, stop collecting training samples. Every 30 days, validate
    // against three changed, time-aligned pairs. Relearn only when their average
    // absolute error is greater than €0.01/kWh.
    const validationDue = ready && (now - lastValidated >= 30 * 24 * 60 * 60 * 1000);
    if (validationDue && pairValid) {
        const lastValidation = validationSamples[validationSamples.length - 1];
        const changedValidation = !lastValidation ||
            Math.abs(lastValidation.x - market) >= 0.0001 ||
            Math.abs(lastValidation.y - allIn) >= 0.0001;
        if (changedValidation) {
            validationSamples.push({
                x: market,
                y: allIn,
                error: Math.abs((market * slope + intercept) - allIn),
                ts: now
            });
            validationSamples = validationSamples.slice(-3);
        }

        if (validationSamples.length >= 3) {
            validationError = validationSamples.reduce((sum, sample) => sum + sample.error, 0) /
                validationSamples.length;
            lastValidated = now;
            if (validationError > 0.01) {
                ready = false;
                relearning = true;
                samples = validationSamples.map(sample => ({ x: sample.x, y: sample.y, ts: sample.ts }));
                collectionStarted = Math.min(...samples.map(sample => Number(sample.ts || now)));
                count = samples.length;
                marketRange = samples.length > 1
                    ? Math.max(...samples.map(sample => sample.x)) - Math.min(...samples.map(sample => sample.x))
                    : 0;
            }
            validationSamples = [];
        }
    } else if (!validationDue) {
        validationSamples = [];
    }

    if (!ready && pairValid) {
        const changed = !lastObservedPair ||
            Math.abs(Number(lastObservedPair.x) - market) >= 0.0001 ||
            Math.abs(Number(lastObservedPair.y) - allIn) >= 0.0001;
        if (changed) {
            samples.push({ x: market, y: allIn, ts: now });
            lastObservedPair = { x: market, y: allIn };
            count = Math.max(count + 1, samples.length);
            if (collectionStarted <= 0) collectionStarted = now;
        }

        // Keep up to 96 changed pairs so a normal 12-hour learning window can
        // capture both low-price and high-price periods. The graph remains live
        // during this period using the current All-in − Market fallback estimate.
        samples = samples.slice(-96);
        if (samples.length > 0 && collectionStarted <= 0) {
            collectionStarted = Number(samples[0].ts || now);
        }

        const collectionDurationMs = collectionStarted > 0 ? now - collectionStarted : 0;
        const minimumCollectionMs = 12 * 60 * 60 * 1000;
        if (count >= 8 && samples.length >= 2) {
            // Group recurring tariff slots by Market price (rounded to €0.0001/kWh)
            // and average their All-in readings. This keeps repeated identical
            // Market values useful without allowing them to fill the low/high fit buckets.
            const groupedByMarket = new Map();
            for (const sample of samples) {
                const key = Math.round(Number(sample.x) * 10000);
                if (!Number.isFinite(key) || !Number.isFinite(Number(sample.y))) continue;
                const group = groupedByMarket.get(key) || { x: key / 10000, ySum: 0, count: 0, ts: 0 };
                group.ySum += Number(sample.y);
                group.count += 1;
                group.ts = Math.max(group.ts, Number(sample.ts || 0));
                groupedByMarket.set(key, group);
            }
            const distinctSamples = [...groupedByMarket.values()]
                .map(group => ({ x: group.x, y: group.ySum / group.count, ts: group.ts }))
                .sort((a, b) => a.x - b.x);
            marketRange = distinctSamples.length > 1
                ? distinctSamples[distinctSamples.length - 1].x - distinctSamples[0].x
                : 0;
            if (collectionDurationMs >= minimumCollectionMs && distinctSamples.length >= 8 && marketRange >= 0.05) {
                const fitSamples = [
                    ...distinctSamples.slice(0, 4),
                    ...distinctSamples.slice(-4)
                ];
                const xs = fitSamples.map(sample => sample.x);
                const meanX = xs.reduce((a, b) => a + b, 0) / fitSamples.length;
                const meanY = fitSamples.reduce((a, sample) => a + sample.y, 0) / fitSamples.length;
                let covariance = 0;
                let variance = 0;
                for (const sample of fitSamples) {
                    covariance += (sample.x - meanX) * (sample.y - meanY);
                    variance += (sample.x - meanX) ** 2;
                }
                if (variance > 1e-8) {
                    const fittedSlope = covariance / variance;
                    const fittedIntercept = meanY - fittedSlope * meanX;
                    if (Number.isFinite(fittedSlope) && Number.isFinite(fittedIntercept) &&
                        fittedSlope >= 0.5 && fittedSlope <= 2.0 &&
                        fittedIntercept >= -0.25 && fittedIntercept <= 1.0) {
                        slope = fittedSlope;
                        intercept = fittedIntercept;
                        ready = true;
                        relearning = false;
                        learnedAt = now;
                        lastValidated = now;
                        validationError = 0;
                        validationSamples = [];
                        count = fitSamples.length;
                        samples = [];
                        collectionStarted = 0;
                    }
                }
            }
        }
        if (!ready) count = Math.max(count, samples.length);
    }

    const model = {
        market_entity: marketEntity,
        all_in_entity: allInEntity,
        samples,
        collection_started: collectionStarted,
        ready,
        slope,
        intercept,
        count,
        range: marketRange,
        learned_at: learnedAt,
        last_validated: lastValidated,
        validation_error: validationError,
        validation_samples: validationSamples,
        last_observed_pair: lastObservedPair,
        relearning,
        restored: storedReady && !sameEntities,
        updated: now
    };
    flow.set('homePvControlHbcAllInModel', model);
    return model;
}

const hbcAllInModel = updateHbcAllInModel();
let hbcPriceType = 'uncertain';
let hbcGraphConversion = 0;
let hbcMarketDifference = NaN;
let hbcAllInDifference = NaN;
if (
    Number.isFinite(hbcCurrentForecastPrice) &&
    Number.isFinite(market) && Number.isFinite(allIn) &&
    stateIsNumeric(marketEntity) && stateIsNumeric(allInEntity) &&
    allIn >= market
) {
    hbcMarketDifference = Math.abs(hbcCurrentForecastPrice - market);
    hbcAllInDifference = Math.abs(hbcCurrentForecastPrice - allIn);
    if (Math.abs(hbcMarketDifference - hbcAllInDifference) >= 0.01) {
        if (hbcMarketDifference < hbcAllInDifference) {
            hbcPriceType = 'market';
            hbcGraphConversion = hbcAllInModel.ready ? hbcAllInModel.intercept : allIn - market;
        } else {
            hbcPriceType = 'all_in';
        }
    }
}

const previousHbcPriceType = flow.get('homePvControlHbcPriceType');
if (previousHbcPriceType && previousHbcPriceType !== hbcPriceType) {
    if (hbcPriceType === 'market') {
        insight('Home PV Control', 'HBC prices', hbcAllInModel.ready ? 'HBC market prices converted to estimated all-in using the learned formula.' : 'HBC market prices converted to estimated all-in using the current difference.');
    } else if (hbcPriceType === 'all_in') {
        insight('Home PV Control', 'HBC prices', 'HBC all-in prices detected.');
    } else {
        insight('Home PV Control', 'HBC prices', 'HBC price type uncertain; original prices shown.');
    }
}
flow.set('homePvControlHbcPriceType', hbcPriceType);
flow.set('homePvControlHbcGraphConversion', hbcGraphConversion);
flow.set('homePvControlHbcPriceModelReady', hbcAllInModel.ready);
flow.set('homePvControlHbcPriceModelSlope', hbcAllInModel.slope);
flow.set('homePvControlHbcPriceModelIntercept', hbcAllInModel.intercept);
flow.set('homePvControlHbcPriceModelSamples', hbcAllInModel.count);
let hbcStatusText = !hasHbc
    ? 'HBC not detected; strategy control paused'
    : hbcStrategyControlAvailable
        ? `HBC detected: ${hbcStrategyEntity}`
        : `HBC detected; strategy options unavailable: ${hbcStrategyEntity}`;

// Log user-facing control transitions once. The flow-context values survive
// normal evaluations and prevent the log from only describing the off state.
const previousEnabledState = flow.get('hpvcPreviousEnabledState');
let masterControlTransitionLogged = false;
if (typeof previousEnabledState === 'boolean' && previousEnabledState !== enabled) {
    if (enabled) {
        insight('Home PV Control', 'Master control', 'HPVC enabled.');
    } else {
        insight('Home PV Control', 'Master control', 'HPVC disabled; no actions sent.');
    }
    masterControlTransitionLogged = true;
}
flow.set('hpvcPreviousEnabledState', enabled);

const previousHbcRequestedState = flow.get('hpvcPreviousHbcRequestedState');
if (
    typeof previousHbcRequestedState === 'boolean' &&
    previousHbcRequestedState !== hbcControlRequested
) {
    if (hbcControlRequested && hasHbc) {
        insight('Home PV Control', 'HBC control', 'HBC control enabled.');
    } else if (!hbcControlRequested) {
        insight('Home PV Control', 'HBC control', 'HBC control disabled.');
    }
}
flow.set('hpvcPreviousHbcRequestedState', hbcControlRequested);

const previousNotificationsState = flow.get('hpvcPreviousNotificationsState');
if (typeof previousNotificationsState === 'boolean' && previousNotificationsState !== notify) {
    insight('Home PV Control', 'Notifications', notify ? 'Notifications enabled' : 'Notifications disabled');
}
flow.set('hpvcPreviousNotificationsState', notify);

const previousSettingsState = flow.get('hpvcPreviousSettingsState');
if (typeof previousSettingsState === 'boolean' && previousSettingsState !== settingsVisible) {
    insight('Home PV Control', 'Settings', settingsVisible ? 'Settings shown.' : 'Settings hidden.');
}
flow.set('hpvcPreviousSettingsState', settingsVisible);

const previousHbcDetectedState = flow.get('hpvcPreviousHbcDetectedState');
if (typeof previousHbcDetectedState === 'boolean' && previousHbcDetectedState !== hasHbc) {
    insight(
        'Home PV Control',
        'HBC detection',
        hasHbc ? `HBC detected: ${hbcStrategyEntity}` : 'HBC unavailable or not detected'
    );
}
flow.set('hpvcPreviousHbcDetectedState', hasHbc);

const previousHbcStrategyControlAvailable = flow.get('hpvcPreviousHbcStrategyControlAvailable');
if (
    typeof previousHbcStrategyControlAvailable === 'boolean' &&
    previousHbcStrategyControlAvailable !== hbcStrategyControlAvailable
) {
    insight(
        'Home PV Control',
        'HBC strategy options',
        hbcStrategyControlAvailable
            ? 'Valid HBC strategy options are available; strategy control resumed.'
            : 'HBC strategy control paused; the configured entity or its option list is unavailable while PV control continues.'
    );
}
flow.set('hpvcPreviousHbcStrategyControlAvailable', hbcStrategyControlAvailable);

const previousDefaultsRestoredEventState = flow.get('hpvcPreviousDefaultsRestoredEventState');
if (
    previousDefaultsRestoredEventState !== undefined &&
    defaultsRestoredEventState &&
    defaultsRestoredEventState !== previousDefaultsRestoredEventState
) {
    insight('Home PV Control', 'Settings', 'Defaults restored.');
}
flow.set('hpvcPreviousDefaultsRestoredEventState', defaultsRestoredEventState);

const marketValid = stateIsNumeric(marketEntity);
const allInValid = stateIsNumeric(allInEntity);
const totalFull = inverters.reduce((s, inv) => s + inv.full_power, 0);
const totalMin = inverters.reduce((s, inv) => s + inv.minimum_power, 0);

// Strict PV cooldown gate.
// Every PV write starts a flow-owned cooldown window. During that window no PV action is allowed.
// As soon as the cooldown window has expired, the current evaluation may make a new PV decision.
const cooldownMs = Math.max(0, cooldownSeconds * 1000);
const cooldownUntilMs = Number(flow.get('homePvControlCooldownUntilMs') || 0);
const previousCooldownActive = flow.get('homePvControlCooldownActive') === true;
const cooldownActiveComputed = cooldownUntilMs > now;
const cooldownJustFinished = previousCooldownActive && !cooldownActiveComputed;
const canChangePv = !cooldownActiveComputed;
let cooldownActiveNow = cooldownActiveComputed;

const wantsMinimumPv = allInValid && allIn <= 0;
const atMinimumPv = inverters.length > 0 && inverters.every(inv => inv.current <= (inv.minimum_power + deadband));
const wasNegativeMinimumMode = flow.get('homePvControlNegativeMinimumActive') === true;

const previousNegativePriceWanted = flow.get('hpvcPreviousNegativePriceWanted');
if (
    typeof previousNegativePriceWanted === 'boolean' &&
    previousNegativePriceWanted &&
    !wantsMinimumPv
) {
    insight('Home PV Control', 'Negative price', `All-in ${allIn.toFixed(3)} €/kWh > 0; normal control resumed.`);
}
flow.set('hpvcPreviousNegativePriceWanted', wantsMinimumPv);

// Separate invalid configuration from temporarily unavailable live states.
// Empty/malformed helper values are configuration problems. Valid configured
// entities that currently report unknown/unavailable/non-numeric are runtime
// input problems and must never be replaced with control values.
let configurationProblems = [];
if (!validEntity(gridEntity)) configurationProblems.push('Grid power sensor');
if (!validEntity(marketEntity)) configurationProblems.push('Market/export price sensor');
if (!validEntity(allInEntity)) configurationProblems.push('All-in price sensor');
if (!validEntity(pvPowerEntity)) configurationProblems.push('PV power sensor');
for (const inv of configuredInverters) {
    if (!validEntity(inv.limit_entity)) configurationProblems.push(`${inv.name} limit entity`);
    if (!(inv.full_power > 0)) configurationProblems.push(`${inv.name} max/full limit`);
    if (inv.minimum_power < 0) configurationProblems.push(`${inv.name} minimum power cannot be negative`);
    if (inv.full_power > 0 && inv.minimum_power >= inv.full_power) configurationProblems.push(`${inv.name} minimum must be lower than full limit`);
}

const runtimeUnavailable = [];
const unavailableInverterSignature = unavailableInverters.map(inv => inv.name).join(',');
const previousUnavailableInverterSignature = String(flow.get('homePvControlUnavailableInverterSignature') || '');
if (unavailableInverterSignature !== previousUnavailableInverterSignature) {
    if (unavailableInverters.length > 0) {
        insight(
            'Home PV Control',
            'Inverter availability',
            `${unavailableInverters.map(inv => inv.name).join(', ')} unavailable; controlling remaining inverters.`
        );
    } else if (previousUnavailableInverterSignature) {
        insight('Home PV Control', 'Inverter availability', 'All configured inverters available; full control resumed.');
    }
    flow.set('homePvControlUnavailableInverterSignature', unavailableInverterSignature);
}
if (validEntity(gridEntity) && !stateIsNumeric(gridEntity)) runtimeUnavailable.push('Grid power sensor');
if (validEntity(marketEntity) && !stateIsNumeric(marketEntity)) runtimeUnavailable.push('Market/export price sensor');
if (validEntity(allInEntity) && !stateIsNumeric(allInEntity)) runtimeUnavailable.push('All-in price sensor');
if (validEntity(pvPowerEntity) && !stateIsNumeric(pvPowerEntity)) runtimeUnavailable.push('PV power sensor');
// Inverter outages are isolated; remaining available inverters continue control.

// Home Assistant helpers may need up to 90 seconds to restore after startup.
// Configuration problems become explicit errors after that grace. Live-state
// outages always block writes: after 90 seconds the status escalates from a
// normal restore wait to a persistent input-unavailable warning.
const restoreGraceMs = 90000;
const nowMs = Date.now();
let configurationMissingSinceMs = Number(flow.get('hpvc_configuration_missing_since_ms') || 0);
let runtimeUnavailableSinceMs = Number(flow.get('hpvc_runtime_unavailable_since_ms') || 0);

if (configurationProblems.length === 0) {
    flow.set('hpvc_configuration_missing_since_ms', 0);
    configurationMissingSinceMs = 0;
} else if (!configurationMissingSinceMs) {
    configurationMissingSinceMs = nowMs;
    flow.set('hpvc_configuration_missing_since_ms', configurationMissingSinceMs);
}

const runtimeInputsRestoredNow = runtimeUnavailable.length === 0 && runtimeUnavailableSinceMs > 0;
if (runtimeUnavailable.length === 0) {
    if (runtimeInputsRestoredNow) {
        insight('Home PV Control', 'Startup', 'Live inputs restored; control resumed.');
    }
    flow.set('hpvc_runtime_unavailable_since_ms', 0);
    runtimeUnavailableSinceMs = 0;
} else if (!runtimeUnavailableSinceMs) {
    runtimeUnavailableSinceMs = nowMs;
    flow.set('hpvc_runtime_unavailable_since_ms', runtimeUnavailableSinceMs);
}

// Remove the obsolete combined timer from earlier builds.
flow.set('hpvc_missing_since_ms', 0);

const waitingForConfigurationRestore =
    configurationProblems.length > 0 &&
    (nowMs - configurationMissingSinceMs) < restoreGraceMs;
const waitingForRuntimeRestore =
    runtimeUnavailable.length > 0 &&
    (nowMs - runtimeUnavailableSinceMs) < restoreGraceMs;

if (!enabled) {
    status = 'Disabled';
    reason = 'Home PV Control is disabled';
    if (!masterControlTransitionLogged) {
        insight('Home PV Control', 'Master control', 'HPVC disabled; no actions sent.');
    }
} else if (waitingForConfigurationRestore) {
    status = 'Waiting for restore';
    reason = 'Waiting for Home Assistant configuration helpers to restore';
    insight('Home PV Control', 'Startup', 'Waiting for Home Assistant configuration helpers to restore');
} else if (configurationProblems.length > 0) {
    status = 'Configuration error';
    reason = `Missing or invalid: ${configurationProblems.join(', ')}`;
    insight('Home PV Control', 'Configuration', reason);
} else if (waitingForRuntimeRestore) {
    status = 'Waiting for inputs';
    reason = `Waiting for live inputs: ${runtimeUnavailable.join(', ')}`;
    insight('Home PV Control', 'Startup', reason);
} else if (runtimeUnavailable.length > 0) {
    status = 'Inputs unavailable';
    reason = `Control paused; unavailable live inputs: ${runtimeUnavailable.join(', ')}`;
    insight('Home PV Control', 'Inputs', reason);
} else if (!thresholdConfigurationValid) {
    status = 'Configuration error';
    reason = thresholdConfigurationError;
    insight('Home PV Control', 'Configuration', thresholdConfigurationError);
} else if (inverters.length === 0 || totalFull <= 0) {
    status = 'Configuration error';
    reason = 'No valid PV inverter limit entities configured';
    insight('Home PV Control', 'Configuration', 'No valid PV inverter limit entities configured');
} else {
    // Target total PV limit: PV power + grid power - target grid power.
    // Example export: PV 2500, grid -600, target -25 => 2500 - 600 + 25 = 1925.
    // Direction-aware import recovery:
    // - When importing while PV is already limited, use the current PV limit as available PV.
    //   This lets HPVC raise the limit after cooldown instead of waiting while buying grid power.
    // - When exporting or balanced, keep using actual PV power so HPVC does not restore while already exporting.
    // Hidden-PV reveal for grid-following batteries:
    // - If PV is limited and grid is still below the export target,
    //   reveal more PV adaptively instead of restoring straight to full power.
    // - Export Start is used to decide when limiting begins; Target export decides reveal recovery.
    // - Mixed inverter states are supported. Hidden PV Reveal operates when one or more inverters remain limited.
    const currentLimitTotal = inverters.reduce((s, inv) => s + inv.current, 0);
    const anyBelowFullNow = inverters.some(inv => inv.current < (inv.full_power - deadband));

    const hbcBatteryCountEntity = 'input_number.house_battery_count';
    const hasHbcBatteryCount = entityExists(hbcBatteryCountEntity);
    const hbcBatteryCount = controlHbc
        ? (hasHbcBatteryCount
            ? Math.round(clamp(helperNum(hbcBatteryCountEntity, 0), 0, 10))
            : 1)
        : 0;
    hbcBatteryCountFallbackActive = controlHbc && !hasHbcBatteryCount;
    const hbcBatterySummary = hbcBatteryPowerSummary(hbcBatteryCount, adaptiveRevealCapWatts, deadband);
    selectedBatteryPowerTotal = hbcBatterySummary.total;
    selectedBatteryIsCharging = hbcBatterySummary.charging;
    selectedBatteryHasChargeHeadroom = hbcBatterySummary.chargeHeadroom;
    selectedBatteryAvailableChargePower = hbcBatterySummary.availableChargePower;
    selectedBatteryAtMaxChargePower = hbcBatterySummary.atMaxChargePower;
    selectedBatteryHighestSoc = hbcBatterySummary.highestSoc;
    selectedBatteryLowestSoc = hbcBatterySummary.lowestSoc;
    selectedBatteryChargingSoc = hbcBatterySummary.chargingSoc;
    selectedBatteryChargePriorityHeadroom = hbcBatterySummary.chargePriorityHeadroom;
    selectedBatteryHighSocHeadroom = hbcBatterySummary.highSocHeadroom;
    selectedBatteryHeadroomBelow90 = hbcBatterySummary.headroomBelow90;
    selectedBatteryHeadroomFrom90To95 = hbcBatterySummary.headroomFrom90To95;
    selectedBatteryHeadroomAtOrAbove95 = hbcBatterySummary.headroomAtOrAbove95;
    selectedBatteryFull = hbcBatterySummary.batteryFull;

    // Give HBC Charge mode priority over low market-price PV limiting while
    // batteries can still absorb more power. Use both the requested price zone and
    // the current strategy so PV is restored immediately, including during the
    // strategy selector's update delay. Preserve the separate all-in <= 0
    // negative-price mode, which intentionally forces minimum PV. Once all active
    // charging batteries are effectively at maximum charge power (95% or more),
    // or all configured batteries are full, normal PV price limiting resumes so
    // excess solar export can be controlled.
    const strategyHysteresis = Math.max(0, hysteresis);
    const chargeEnter = chargePrice;
    const chargeExit = chargePrice + strategyHysteresis;
    const hbcChargeRequested =
        controlHbc &&
        allInValid &&
        !wantsMinimumPv &&
        !selectedBatteryFull &&
        (
            allIn <= chargeEnter ||
            (currentStrategy === chargeStrategy && allIn <= chargeExit)
        );

    // Track startup and telemetry independently per battery. One battery that
    // is already charging must not consume another battery's startup grace.
    const chargeAbsorptionLogicVersion = '1.3.0-per-battery-r3';
    let chargeAbsorptionStates = flow.get('homePvControlChargeAbsorptionStates');
    if (
        flow.get('homePvControlChargeAbsorptionLogicVersion') !== chargeAbsorptionLogicVersion ||
        !chargeAbsorptionStates ||
        typeof chargeAbsorptionStates !== 'object'
    ) {
        flow.set('homePvControlChargeAbsorptionLogicVersion', chargeAbsorptionLogicVersion);
        chargeAbsorptionStates = {};
        flow.set('homePvControlChargeAbsorptionState', null);
    }

    let chargeStartupGrace = false;
    let chargeTelemetryGrace = false;
    for (const battery of hbcBatterySummary.batteries) {
        let state = chargeAbsorptionStates[battery.index];
        if (!state || typeof state !== 'object') {
            state = { requestSince: 0, seenCharging: false, lastChargingAt: 0, lastHadHeadroom: false };
        }

        if (!hbcChargeRequested) {
            state = { requestSince: 0, seenCharging: false, lastChargingAt: 0, lastHadHeadroom: false };
        } else {
            if (!state.requestSince) state.requestSince = now;
            if (battery.charging) {
                state.seenCharging = true;
                state.lastChargingAt = now;
                // Only meaningful, known-max, below-90% headroom can be remembered
                // for full-PV telemetry grace.
                state.lastHadHeadroom = battery.fullPvHeadroom === true;
            }

            const startupWindowMs = battery.socKnown
                ? (!battery.high90 ? 60000 : 0)
                : 15000;
            if (
                !state.seenCharging &&
                startupWindowMs > 0 &&
                (now - Number(state.requestSince || now)) <= startupWindowMs
            ) {
                chargeStartupGrace = true;
            }
            if (
                state.seenCharging &&
                !battery.charging &&
                state.lastHadHeadroom === true &&
                (now - Number(state.lastChargingAt || 0)) <= 30000
            ) {
                chargeTelemetryGrace = true;
            }
        }
        chargeAbsorptionStates[battery.index] = state;
    }
    // Remove stale entries when the configured battery count is reduced.
    for (const key of Object.keys(chargeAbsorptionStates)) {
        if (Number(key) > hbcBatteryCount) delete chargeAbsorptionStates[key];
    }
    flow.set('homePvControlChargeAbsorptionStates', chargeAbsorptionStates);
    // Reuse Hidden PV Reveal's existing high-SOC taper protection for Charge
    // priority. From 90% SOC, normal export limiting remains active and Reveal
    // probes available battery absorption in progressively smaller SOC-based steps:
    // 200 W at 90–94%, 100 W at 95–96%, 50 W at 97–98%, and 25 W at 99%.
    // A previously detected taper pause blocks full-PV priority until the same
    // existing recovery test clears it.
    const currentBatteryChargePowerForTaper = Math.max(0, -selectedBatteryPowerTotal);
    const existingBatteryTaperPause = flow.get('homePvControlBatteryTaperPause') || {};
    const existingBatteryTaperRecovered =
        existingBatteryTaperPause.active === true &&
        (
            (selectedBatteryChargingSoc !== null && selectedBatteryChargingSoc < 90) ||
            currentBatteryChargePowerForTaper >= (
                Number(existingBatteryTaperPause.battery_charge_power || 0) + Math.max(75, deadband * 3)
            )
        );
    if (existingBatteryTaperRecovered) {
        flow.set('homePvControlBatteryTaperPause', null);
        flow.set('homePvControlRevealPauseReason', '');
    }
    // Multi-battery Charge Priority is decided per battery, never from one
    // combined lowest/highest SOC. Any actively charging battery with useful
    // headroom below 90% may keep full PV available. If headroom exists only in
    // batteries at 90% or above, normal limiting stays active and the existing
    // adaptive Reveal/taper logic probes that headroom safely.
    // Full-PV Charge Priority is granted only by a qualifying below-90% battery,
    // either through measured meaningful headroom or that battery's own startup/
    // telemetry grace. High-SOC adaptive headroom and taper pauses must not block
    // a separate lower-SOC battery from starting or continuing to charge.
    const hbcChargePriority =
        hbcChargeRequested &&
        (
            (selectedBatteryIsCharging && selectedBatteryChargePriorityHeadroom) ||
            chargeStartupGrace ||
            chargeTelemetryGrace
        );

    // PV price hysteresis applies only when exiting low-price limiting.
    // HBC Charge priority suspends that mode only while batteries have useful
    // charge headroom; at maximum charge power, normal export limiting resumes.
    const storedPriceLimitingActive = flow.get('homePvControlPriceLimitingActive');
    let priceLimitingActive = typeof storedPriceLimitingActive === 'boolean'
        ? storedPriceLimitingActive
        : (marketValid && (market <= limitingPrice || (market <= pvRestorePrice && anyBelowFullNow)));
    if (!marketValid || hbcChargePriority) priceLimitingActive = false;
    else if (market <= limitingPrice) priceLimitingActive = true;
    else if (market > pvRestorePrice) priceLimitingActive = false;
    flow.set('homePvControlPriceLimitingActive', priceLimitingActive);

    const pvFullyRestoredNow = inverters.length > 0 && currentLimitTotal >= (totalFull - deadband);
    const pvExactlyRestoredNow = inverters.length > 0 && inverters.every(inv => inv.current >= (inv.full_power - 1));
    hiddenPvRemaining = Math.max(0, totalFull - currentLimitTotal);
    const batteryHeadroom = Math.max(0, selectedBatteryAvailableChargePower);
    // Battery BMS charge taper commonly starts near high SOC. Limit reveal steps there
    // so configured max-charge power is not mistaken for currently absorbable power.
    // Per-battery SOC probe ceilings are already included in batteryHeadroom.
    // Keep only the fleet-wide 800 W safety cap here so one high-SOC battery's
    // smaller probe does not incorrectly cap a separate battery with more headroom.
    effectiveRevealCap = adaptiveRevealCapWatts;
    // Expose and use actionable per-battery probe headroom, not the battery's
    // current charging power. High-SOC probes are repeated only after the
    // response guard confirms that extra PV was safely absorbed.
    effectiveBatteryHeadroom = Math.max(0, Math.min(batteryHeadroom, effectiveRevealCap));
    targetTolerance = Math.round(Math.min(
        Math.max(deadband * 2, effectiveBatteryHeadroom * 0.25),
        150
    ));
    const hiddenPvRevealWindow = controlHbc && !pvFullyRestoredNow && anyBelowFullNow && grid >= exportStart && grid < (exportTarget + targetTolerance);
    exportTargetMargin = Math.max(0, (exportTarget + targetTolerance) - grid);
    adaptiveRevealIncrease = Math.round(Math.min(
        effectiveRevealCap,
        effectiveBatteryHeadroom,
        exportTargetMargin,
        hiddenPvRemaining
    ));

    // Real-PV response guard, aligned with the proven v1.2.0 behavior.
    // Evaluate each reveal request once, after inverter/PV readings have had time to settle.
    const revealGuardLogicVersion = '1.3.0-independent-achievable-reveal-scoring-r8';
    if (flow.get('homePvControlRevealGuardLogicVersion') !== revealGuardLogicVersion) {
        flow.set('homePvControlRevealGuardLogicVersion', revealGuardLogicVersion);
        flow.set('homePvControlLastHiddenPvReveal', null);
        flow.set('homePvControlRevealResponseHistory', []);
        flow.set('homePvControlRevealStabilityScore', 100);
        flow.set('homePvControlLastNoPvResponsePause', null);
        flow.set('homePvControlBatteryTaperPause', null);
    }

    const lastReveal = flow.get('homePvControlLastHiddenPvReveal') || {};
    const currentBatteryPowerTimestampMs = hbcBatterySummary.batteries.reduce(
        (latest, battery) => Math.max(latest, Number(battery.powerTimestampMs || 0)),
        0
    );
    const previousRevealPending =
        lastReveal &&
        lastReveal.pending === true &&
        lastReveal.evaluated !== true &&
        Number.isFinite(Number(lastReveal.pv_power)) &&
        Number.isFinite(Number(lastReveal.increase));
    const revealAgeMs = previousRevealPending ? Math.max(0, now - Number(lastReveal.ts || now)) : 0;
    // Allow inverter, PV, battery and grid telemetry to settle before scoring a reveal.
    // Reveal Accuracy is scored only after Home Assistant has received a fresh
    // grid sample following the reveal request. This avoids false low scores
    // caused by evaluating the same pre-reveal grid reading.
    const revealSettleMs = Math.max(25000, cooldownMs);
    const revealTelemetryTimeoutMs = Math.max(90000, revealSettleMs + 60000);
    const currentGridTimestampMs = entityTimestampMs(gridEntity);
    const currentPvTimestampMs = entityTimestampMs(pvPowerEntity);
    const gridUpdatedAfterReveal =
        previousRevealPending &&
        currentGridTimestampMs > Number(lastReveal.grid_timestamp_ms || 0);
    const pvUpdatedAfterReveal =
        previousRevealPending &&
        currentPvTimestampMs > Number(lastReveal.pv_timestamp_ms || 0);

    // Score only after the requested inverter limits are visible.
    const revealWriteTolerance = Math.max(2, Math.min(deadband, 10));
    const revealRequestedLimits = Array.isArray(lastReveal.requested_limits)
        ? lastReveal.requested_limits
        : [];
    const revealWriteSettled =
        previousRevealPending &&
        revealRequestedLimits.length > 0 &&
        revealRequestedLimits.every(item => {
            const actual = numEntity(item.entity, NaN);
            return Number.isFinite(actual) &&
                Math.abs(actual - Number(item.value)) <= revealWriteTolerance;
        });

    const revealReadyToEvaluate =
        previousRevealPending &&
        revealAgeMs >= revealSettleMs &&
        gridUpdatedAfterReveal &&
        pvUpdatedAfterReveal &&
        revealWriteSettled;
    const revealTelemetryTimedOut =
        previousRevealPending &&
        revealAgeMs >= revealTelemetryTimeoutMs &&
        (!gridUpdatedAfterReveal || !pvUpdatedAfterReveal);
    const revealWriteTimedOut =
        previousRevealPending &&
        revealAgeMs >= revealTelemetryTimeoutMs &&
        gridUpdatedAfterReveal &&
        pvUpdatedAfterReveal &&
        !revealWriteSettled;
    const batteryPowerUpdatedAfterReveal =
        previousRevealPending &&
        currentBatteryPowerTimestampMs > Number(lastReveal.battery_power_timestamp_ms || 0);
    const previousPvResponse = previousRevealPending
        ? Math.max(0, pvPower - Number(lastReveal.pv_power))
        : 0;
    const requiredPvResponse = previousRevealPending
        ? Math.max(deadband, Number(lastReveal.increase) * 0.25)
        : 0;
    const currentBatteryChargePower = currentBatteryChargePowerForTaper;
    const previousBatteryChargePower = previousRevealPending
        ? Math.max(0, Number(lastReveal.battery_charge_power || 0))
        : 0;
    // Only credit a battery-charge response when Home Assistant has received a
    // new power sample after the reveal. Stable old numeric values remain valid
    // for eligibility, but are not evidence that the probe was absorbed.
    revealBatteryChargeResponse = previousRevealPending && batteryPowerUpdatedAfterReveal
        ? Math.max(0, currentBatteryChargePower - previousBatteryChargePower)
        : 0;
    revealExportIncrease = previousRevealPending && Number.isFinite(Number(lastReveal.grid_power))
        ? Math.max(0, Number(lastReveal.grid_power) - grid)
        : 0;
    const requiredBatteryResponse = previousRevealPending
        ? Math.max(25, Number(lastReveal.increase) * 0.20)
        : 0;
    const highSocDuringReveal = previousRevealPending && Number(lastReveal.battery_soc) >= 90;

    revealResponseHistory = Array.isArray(flow.get('homePvControlRevealResponseHistory'))
        ? flow.get('homePvControlRevealResponseHistory').slice(-2)
        : [];
    revealStabilityScore = Number(flow.get('homePvControlRevealStabilityScore'));
    if (!Number.isFinite(revealStabilityScore)) revealStabilityScore = 100;

    if (revealReadyToEvaluate) {
        const responseRatio = requiredPvResponse > 0
            ? Math.min(1.5, previousPvResponse / requiredPvResponse)
            : 1;
        const batteryResponseRatio = requiredBatteryResponse > 0
            ? Math.min(1.5, revealBatteryChargeResponse / requiredBatteryResponse)
            : 1;
        const requestedReveal = Math.max(1, Number(lastReveal.increase) || 0);
        const revealTarget = Number.isFinite(Number(lastReveal.target_grid))
            ? Number(lastReveal.target_grid)
            : exportTarget;
        const beforeTargetError = Math.abs(Number(lastReveal.grid_power) - revealTarget);
        const afterTargetError = Math.abs(grid - revealTarget);
        const gridImprovement = Math.max(0, beforeTargetError - afterTargetError);

        // Determine the achievable response independently from the response being
        // scored. The estimate is captured before the reveal from PV output versus
        // the active inverter limit. This prevents a weak observed response from
        // shrinking its own scoring denominator.
        const storedAchievableIncrease = Number(lastReveal.achievable_increase);
        const achievablePvIncrease = Math.max(
            0,
            Math.min(
                requestedReveal,
                Number.isFinite(storedAchievableIncrease)
                    ? storedAchievableIncrease
                    : requestedReveal
            )
        );
        const pvAvailabilityMargin = Math.max(deadband, 50);
        const requestedTargetTotal = Number(lastReveal.target_total || 0);
        const preRevealPvPower = Number(lastReveal.pv_power || 0);
        const pvAvailabilityDrop = Math.max(0, preRevealPvPower - pvPower);
        const pvAvailabilityLimited =
            pvAvailabilityDrop >= Math.max(deadband, requestedReveal * 0.25) &&
            requestedTargetTotal > 0 &&
            pvPower < (requestedTargetTotal - pvAvailabilityMargin);

        if (pvAvailabilityLimited) {
            revealAccuracySkipReason = 'pv_availability_changed';
            revealEffectiveness = null;
        } else {
            revealAccuracyExpectedResponse = Math.max(
                1,
                Math.min(achievablePvIncrease, beforeTargetError)
            );
            revealAccuracyWeight = Math.max(deadband, requestedReveal);
            revealEffectiveness = Math.round(
                Math.max(0, Math.min(
                    100,
                    (gridImprovement / revealAccuracyExpectedResponse) * 100
                ))
            );
        }

        // Keep absorption efficiency as a separate diagnostic; it no longer drives
        // Daily Reveal Accuracy or overshoot classification.
        const safelyAbsorbedPv = Math.max(
            revealBatteryChargeResponse,
            previousPvResponse - revealExportIncrease
        );
        const usefulRevealedPv = Math.max(
            0,
            Math.min(requestedReveal, previousPvResponse, safelyAbsorbedPv)
        );
        revealAbsorptionEffectiveness = Math.round(
            Math.max(0, Math.min(100, (usefulRevealedPv / requestedReveal) * 100))
        );
        const revealOvershootWatts = Math.max(0, revealTarget - grid - deadband);
        revealOvershotTarget = revealOvershootWatts > 0;
        const exportLeakThreshold = Math.max(deadband, Number(lastReveal.increase) * 0.25);
        const batteryTaperResponse =
            highSocDuringReveal &&
            revealBatteryChargeResponse < requiredBatteryResponse &&
            revealExportIncrease >= exportLeakThreshold;
        const usefulResponse =
            previousPvResponse >= requiredPvResponse &&
            (revealBatteryChargeResponse >= requiredBatteryResponse || revealExportIncrease < exportLeakThreshold);

        if (pvAvailabilityLimited) {
            insight('Home PV Control', 'Hidden PV Reveal',
                'Evaluation skipped: available PV changed during the response window.');
            flow.set('homePvControlLastHiddenPvReveal', {
                ...lastReveal,
                evaluated: true,
                evaluation_skipped: revealAccuracySkipReason,
                evaluation_skipped_ts: now
            });
        } else {
            if (batteryTaperResponse) {
                revealStabilityScore = Math.min(revealStabilityScore, 25);
                hiddenPvRevealBatteryTaper = true;
                flow.set('homePvControlBatteryTaperPause', {
                    active: true,
                    battery_charge_power: currentBatteryChargePower,
                    battery_soc: selectedBatteryChargingSoc,
                    battery_response: revealBatteryChargeResponse,
                    export_increase: revealExportIncrease,
                    ts: now
                });
            } else if (usefulResponse) {
                revealStabilityScore = Math.min(100, revealStabilityScore + 15);
            } else if (responseRatio >= 0.5 || batteryResponseRatio >= 0.5) {
                revealStabilityScore = Math.max(0, revealStabilityScore - 10);
            } else {
                revealStabilityScore = Math.max(0, revealStabilityScore - 30);
            }

            revealResponseHistory.push({
                response: Math.round(previousPvResponse),
                required: Math.round(requiredPvResponse),
                achievable_response: Math.round(revealAccuracyExpectedResponse),
                weight: Math.round(revealAccuracyWeight),
                battery_response: Math.round(revealBatteryChargeResponse),
                battery_required: Math.round(requiredBatteryResponse),
                export_increase: Math.round(revealExportIncrease),
                overshot_target: revealOvershotTarget,
                target_effectiveness: revealEffectiveness,
                absorption_effectiveness: revealAbsorptionEffectiveness,
                taper: batteryTaperResponse,
                ratio: Math.round(responseRatio * 100) / 100,
                ok: usefulResponse,
                score: Math.round(revealStabilityScore),
                ts: now
            });
            revealResponseHistory = revealResponseHistory.slice(-3);
            flow.set('homePvControlLastHiddenPvReveal', { ...lastReveal, evaluated: true });
        }
    } else if (revealTelemetryTimedOut) {
        // Do not turn missing telemetry into a 0% accuracy sample or a poor-response penalty.
        // Release the pending probe after the timeout so future reveals are not blocked.
        const revealTelemetryTimeoutSeconds = Math.round(revealTelemetryTimeoutMs / 1000);
        const missingTelemetry = [
            !gridUpdatedAfterReveal ? 'grid' : '',
            !pvUpdatedAfterReveal ? 'PV' : ''
        ].filter(Boolean).join(' and ');
        insight(
            'Home PV Control',
            'Hidden PV Reveal',
            `Evaluation skipped: ${missingTelemetry} telemetry did not update within ${revealTelemetryTimeoutSeconds} s after reveal.`
        );
        flow.set('homePvControlLastHiddenPvReveal', {
            ...lastReveal,
            evaluated: true,
            evaluation_skipped: 'stale_reveal_telemetry',
            evaluation_skipped_ts: now
        });
    } else if (revealWriteTimedOut) {
        insight(
            'Home PV Control',
            'Hidden PV Reveal',
            'Evaluation skipped: inverter-limit write did not settle before the verification timeout.'
        );
        flow.set('homePvControlLastHiddenPvReveal', {
            ...lastReveal,
            evaluated: true,
            evaluation_skipped: 'unsettled_inverter_write',
            evaluation_skipped_ts: now
        });
    }
    revealPoorResponseCount = revealResponseHistory.filter(r => r && r.ok === false).length;

    const batteryTaperPause = flow.get('homePvControlBatteryTaperPause') || {};
    const batteryTaperRecovered =
        batteryTaperPause.active === true &&
        (
            (selectedBatteryChargingSoc !== null && selectedBatteryChargingSoc < 90) ||
            currentBatteryChargePower >= (Number(batteryTaperPause.battery_charge_power || 0) + Math.max(75, deadband * 3))
        );
    if (batteryTaperRecovered) {
        flow.set('homePvControlBatteryTaperPause', null);
        revealStabilityScore = Math.max(revealStabilityScore, 60);
    } else if (existingBatteryTaperRecovered) {
        // The same recovery was already cleared before the Charge-priority decision.
        revealStabilityScore = Math.max(revealStabilityScore, 60);
    }
    hiddenPvRevealBatteryTaper =
        !batteryTaperRecovered &&
        batteryTaperPause.active === true &&
        selectedBatteryChargingSoc !== null &&
        selectedBatteryChargingSoc >= 90;
    if (hiddenPvRevealBatteryTaper) {
        revealBatteryChargeResponse = Number(batteryTaperPause.battery_response || 0);
        revealExportIncrease = Number(batteryTaperPause.export_increase || 0);
    }

    const lastNoPvPause = flow.get('homePvControlLastNoPvResponsePause') || {};
    const lastNoPvPausePvPower = Number(lastNoPvPause.pv_power || 0);
    sunRecoveryDetected =
        lastNoPvPause &&
        lastNoPvPause.active === true &&
        (
            pvPower >= (lastNoPvPausePvPower + Math.max(75, deadband * 3)) ||
            grid < exportStart
        );

    if (sunRecoveryDetected) {
        revealStabilityScore = Math.max(revealStabilityScore, 60);
    }

    const consecutivePoorRevealResponses = revealResponseHistory
        .slice(-2)
        .filter(item => item && item.ok === false)
        .length;
    const lowRevealStability =
        !sunRecoveryDetected &&
        revealReadyToEvaluate &&
        revealStabilityScore < 40 &&
        consecutivePoorRevealResponses >= 2;

    hiddenPvRevealNoPvResponse =
        (
            hiddenPvRevealBatteryTaper ||
            lowRevealStability
        ) &&
        grid >= exportStart &&
        grid <= importRecalc;
    const revealStartThreshold = exportTarget + deadband;
    revealHiddenPv =
        hiddenPvRevealWindow &&
        grid > revealStartThreshold &&
        selectedBatteryHasChargeHeadroom &&
        adaptiveRevealIncrease > 0 &&
        !hiddenPvRevealNoPvResponse &&
        !previousRevealPending;
    const previousHiddenPvRevealPaused = flow.get('homePvControlHiddenPvRevealPaused') === true;
    previousRevealPauseReason = String(flow.get('homePvControlRevealPauseReason') || '');
    const previousHiddenPvRevealActive = flow.get('homePvControlHiddenPvRevealActive') === true;
    const previousHiddenPvRevealCompleted = flow.get('homePvControlHiddenPvRevealCompleted') === true;

    if (hiddenPvRevealWindow) {
        if (hiddenPvRevealBatteryTaper) revealPauseReason = 'battery_taper';
        else if (hiddenPvRevealNoPvResponse) revealPauseReason = 'low_stability';
        else if (!selectedBatteryHasChargeHeadroom) revealPauseReason = 'no_probe_headroom';
        else if (adaptiveRevealIncrease <= 0) revealPauseReason = 'no_reveal_margin';
    }
    hiddenPvRevealPaused = revealPauseReason !== '';
    hiddenPvRevealResumed = previousHiddenPvRevealPaused && revealPauseReason === '' && revealHiddenPv;
    hiddenPvRevealCompleted = previousHiddenPvRevealActive && pvExactlyRestoredNow;
    hiddenPvRevealFinalRestore = previousHiddenPvRevealActive && pvFullyRestoredNow && !pvExactlyRestoredNow;
    hiddenPvRevealCompletedResumed = previousHiddenPvRevealCompleted && revealHiddenPv;
    const previousHbcBatteryCountFallbackActive = flow.get('homePvControlHbcBatteryCountFallbackActive') === true;
    if (hbcBatteryCountFallbackActive && !previousHbcBatteryCountFallbackActive) {
        insight('Home PV Control', 'HBC battery count', 'input_number.house_battery_count missing; using 1 battery fallback for hidden PV reveal');
    }
    if (hiddenPvRevealCompleted) {
        insight('Home PV Control', 'PV limit', 'Full PV restored.');
    }
    if (hiddenPvRevealCompletedResumed && previousRevealPauseReason === 'battery_not_charging') {
        insight('Home PV Control', 'Hidden PV Reveal', 'Battery charging recovered; reveal resumed.');
    } else if (hiddenPvRevealCompletedResumed && previousRevealPauseReason === 'low_stability') {
        insight('Home PV Control', 'Hidden PV Reveal', 'PV response recovered; reveal resumed.');
    }
    const revealIncrease = revealHiddenPv
        ? adaptiveRevealIncrease
        : 0;
    importRecalcActive = grid > importRecalc && anyBelowFullNow;
    const pvForTarget = importRecalcActive
        ? Math.max(pvPower, currentLimitTotal)
        : pvPower;
    const rawTarget = revealHiddenPv
        ? currentLimitTotal + revealIncrease
        : (!anyBelowFullNow && grid > importRecalc
            ? totalFull
            : pvForTarget + grid - exportTarget);
    targetTotal = Math.round(clamp(rawTarget, totalMin, totalFull));

    if (revealHiddenPv) {
        targets = distributeIncreaseTargets(inverters, targetTotal - currentLimitTotal, deadband)
            .map(t => ({
                ...t,
                changed: inverterWriteRequired(t.current, t.target, 5),
                clamped: t.target <= t.minimum_power || t.target >= t.full_power
            }));
    } else {
        const activeTotalFull = inverters.reduce((sum, inv) => sum + inv.full_power, 0);
        targets = inverters.map(inv => ({
            name: inv.name,
            entity: inv.limit_entity,
            current: inv.current,
            target: clamp(
                activeTotalFull > 0
                    ? targetTotal * (inv.full_power / activeTotalFull)
                    : targetTotal / Math.max(1, inverters.length),
                inv.minimum_power,
                inv.full_power
            ),
            full_power: inv.full_power,
            minimum_power: inv.minimum_power,
            clamped: false,
            changed: false
        }));

        // Redistribute residual watts after one or more inverters hit min/max.
        for (let pass = 0; pass < Math.max(1, targets.length * 3); pass++) {
            const achieved = targets.reduce((sum, t) => sum + t.target, 0);
            const residual = targetTotal - achieved;
            if (Math.abs(residual) < 0.5) break;

            const candidates = targets.filter(t =>
                residual > 0
                    ? t.target < t.full_power - 0.5
                    : t.target > t.minimum_power + 0.5
            );
            if (candidates.length === 0) break;

            const totalRoom = candidates.reduce((sum, t) => sum + (
                residual > 0
                    ? t.full_power - t.target
                    : t.target - t.minimum_power
            ), 0);
            if (totalRoom <= 0) break;

            for (const t of candidates) {
                const room = residual > 0
                    ? t.full_power - t.target
                    : t.target - t.minimum_power;
                t.target = clamp(
                    t.target + residual * (room / totalRoom),
                    t.minimum_power,
                    t.full_power
                );
            }
        }

        targets = targets.map(t => {
            const target = Math.round(t.target);
            return {
                ...t,
                target,
                clamped: target <= t.minimum_power || target >= t.full_power,
                changed: inverterWriteRequired(t.current, target, 5)
            };
        });
    }

    flow.set('homePvControlInverterDiagnostics', {
        ts: now,
        requestedTotal: targetTotal,
        achievedTargetTotal: targets.reduce((sum, t) => sum + t.target, 0),
        unavailable: unavailableInverters.map(inv => ({
            name: inv.name,
            entity: inv.limit_entity,
            reason: 'live limit unavailable'
        })),
        inverters: targets.map(t => ({
            name: t.name,
            entity: t.entity,
            current: t.current,
            calculatedTarget: t.target,
            requestedTarget: null,
            difference: null,
            minimum: t.minimum_power,
            maximum: t.full_power,
            clamped: t.clamped === true,
            writeRequired: false,
            action: 'none'
        }))
    });

    const targetChanged = targets.some(t => t.changed);
    const targetIsFull = targets.length > 0 && targets.every(t => t.target >= (t.full_power - deadband));
    const targetIsMinimum = targets.length > 0 && targets.every(t => t.target <= (t.minimum_power + deadband));
    const shouldForceMinimum =
    canChangePv &&
    !atMinimumPv &&
    (
        wantsMinimumPv ||
        (
            targetIsMinimum &&
            marketValid &&
            priceLimitingActive &&
            pvPower > minPvPower &&
            grid < exportStart
        )
    );

    const shouldFinalRestoreHiddenPv =
        hiddenPvRevealFinalRestore &&
        anyBelowFullNow &&
        !wantsMinimumPv &&
        canChangePv;

    const shouldRestore =
        anyBelowFullNow &&
        !wantsMinimumPv &&
        canChangePv &&
        (
            (wasNegativeMinimumMode && atMinimumPv) ||
            hbcChargePriority ||
            !marketValid ||
            market > pvRestorePrice ||
            persistentNightRestore ||
            targetIsFull
        );

    const shouldAdjust =
        !targetIsFull &&
        !targetIsMinimum &&
        !wantsMinimumPv &&
        marketValid &&
        targetChanged &&
        priceLimitingActive &&
        (pvPower > minPvPower || importRecalcActive || revealHiddenPv) &&
        canChangePv &&
        (
            revealHiddenPv ||
            grid < exportStart ||
            importRecalcActive
        );

    if (shouldForceMinimum) {
        pvAction = 'minimum';
        status = wantsMinimumPv ? 'PV minimum - negative price' : 'PV minimum limit';
        reason = wantsMinimumPv
            ? `All-in ${allIn.toFixed(3)} €/kWh <= 0; minimum PV`
            : 'Calculated target is minimum power';
    } else if (shouldFinalRestoreHiddenPv) {
        pvAction = 'final_restore';
        status = 'PV restored';
        reason = 'Reveal complete; restoring full PV';
    } else if (shouldRestore) {
        pvAction = 'restore';
        status = 'PV restored';
        if (wasNegativeMinimumMode && atMinimumPv) reason = 'Leaving negative price minimum mode';
        else if (hbcChargePriority) reason = 'HBC Charge active; restoring full PV for battery charging';
        else if (!marketValid) reason = 'Market/export price unavailable';
        else if (persistentNightRestore) reason = sunAvailable
            ? 'Sunset +120s; restoring full PV'
            : `PV ${Math.round(pvPower)}W < Night ${Math.round(nightRestorePower)}W for 120s; restoring full PV`;
        else if (market > pvRestorePrice) reason = `Market/export price ${market.toFixed(4)} €/kWh exceeded the PV restore threshold ${pvRestorePrice.toFixed(4)} €/kWh (limit + hysteresis)`;
        else if (targetIsFull) reason = 'Calculated target is full power';
        else reason = 'Restore condition';
    } else if (shouldAdjust) {
        pvAction = 'adjust';
        status = 'PV dynamically adjusted';
        if (revealHiddenPv) {
            const targetRelation = grid > exportTarget ? '>' : (grid < exportTarget ? '<' : '=');
            reason = `Grid ${Math.round(grid)}W ${targetRelation} Target ${Math.round(exportTarget)}W`;
        }
        else if (grid < exportStart) reason = `Export ${Math.round(grid)}W < Start ${Math.round(exportStart)}W`;
        else if (grid > importRecalc) reason = `Import ${Math.round(grid)}W > Restore ${Math.round(importRecalc)}W`;
        else reason = 'Dynamic adjustment';
    } else {
        status = wantsMinimumPv ? 'PV minimum active' : (priceLimitingActive ? 'Monitoring low price' : 'PV full / price OK');
        if (!controlHbc) {
            // HBC/reveal is disabled: keep runtime reasons strictly about PV control.
            flow.set('homePvControlRevealBlockKey', '');
            reason = targetIsMinimum && atMinimumPv
                ? 'PV already at minimum; waiting until a higher target is needed'
                : (canChangePv ? 'No target change needed' : 'PV cooldown active');
        } else if (hiddenPvRevealPaused) {
            let revealBlockKey = '';
            if (hiddenPvRevealBatteryTaper) {
                revealBlockKey = 'battery_charge_taper';
                const socText = Number.isFinite(selectedBatteryChargingSoc) ? ` at ${Math.round(selectedBatteryChargingSoc)}% SOC` : '';
                reason = `Reveal paused: charging batteries tapering${socText}.`;
            } else if (hiddenPvRevealNoPvResponse) {
                revealBlockKey = 'low_stability';
                reason = `Reveal paused: low PV response (stability ${Math.round(revealStabilityScore)}%).`;
            } else if (selectedBatteryFull) {
                revealBlockKey = 'battery_full';
                const socText = Number.isFinite(selectedBatteryHighestSoc) ? ` (${Math.round(selectedBatteryHighestSoc)}% SOC)` : '';
                reason = `Reveal skipped: batteries full${socText}.`;
            } else if (selectedBatteryAtMaxChargePower) {
                revealBlockKey = 'battery_at_max_charge_power';
                reason = 'Reveal skipped: batteries at max charge.';
            } else {
                revealBlockKey = 'no_probe_headroom';
                reason = 'Reveal skipped: no eligible battery probe headroom above the configured deadband.';
            }

            // Reveal-block Insights are state transitions, not periodic reminders.
            // Keep the last reason across brief reveal-window exits so the same
            // unchanged condition cannot be logged again every minute.
            const previousRevealBlockKey = String(flow.get('homePvControlRevealBlockKey') || '');
            if (revealBlockKey !== previousRevealBlockKey) {
                insight('Home PV Control', 'Hidden PV Reveal', reason);
                flow.set('homePvControlRevealBlockKey', revealBlockKey);
            }
        } else if (revealHiddenPv) {
            // A real reveal resumption clears the previous block reason.
            flow.set('homePvControlRevealBlockKey', '');
            reason = `Reveal ${revealIncrease}W <= Deadband ${Math.round(deadband)}W; waiting.`;
        } else {
            reason = targetIsMinimum && atMinimumPv
                ? 'PV already at minimum; waiting until higher target is needed'
                : (canChangePv ? 'No target change needed' : 'PV cooldown active');
        }
    }

    // Track whether the current minimum state came from negative-price mode.
    // This prevents the export-limiting minimum path from restoring and limiting in a loop.
    if (wantsMinimumPv) {
        flow.set('homePvControlNegativeMinimumActive', true);
    } else if (wasNegativeMinimumMode && (pvAction === 'restore' || !atMinimumPv)) {
        flow.set('homePvControlNegativeMinimumActive', false);
    }

    // Build inverter service messages as a list for split node.
    let calls = [];
    if (pvAction === 'minimum') {
        let changedMinimum = [];
        for (const inv of inverters) {
            if (inverterWriteRequired(inv.current, inv.minimum_power, 5)) {
                calls.push(serviceMsg('number', 'set_value', { value: inv.minimum_power }, { entity_id: inv.limit_entity }));
                changedMinimum.push(`${inv.name} ${inv.current}→${inv.minimum_power}W`);
            }
        }
        if (changedMinimum.length > 0) {
            if (wantsMinimumPv) {
                insight(
                    'Home PV Control',
                    'Negative price',
                    `All-in ${allIn.toFixed(3)} €/kWh <= 0; minimum PV; ${changedMinimum.join(', ')}`
                );
            } else {
                insight(
                    'Home PV Control',
                    'PV limit',
                    `Calculated target reached minimum power; requested ${changedMinimum.join(', ')}`
                );
            }
        }
        if (notify) {
            notification = {
                title: wantsMinimumPv ? 'PV minimum - negative price' : 'PV minimum limit',
                message:
`PV requested at minimum.

Reason: ${reason}

All-in price: ${formatNotificationPrice(allIn)} €/kWh
Market/export price: ${formatNotificationPrice(market)} €/kWh
PV power: ${pvPower} W
Grid power: ${grid} W

Inverters changed: ${calls.length}`
            };
        }
    } else if (pvAction === 'final_restore') {
        let changedFinalRestore = [];
        for (const inv of inverters) {
            if (inverterWriteRequired(inv.current, inv.full_power, 5)) {
                calls.push(serviceMsg('number', 'set_value', { value: inv.full_power }, { entity_id: inv.limit_entity }));
                changedFinalRestore.push(`${inv.name} ${inv.current}→${inv.full_power}W`);
            }
        }
        if (changedFinalRestore.length > 0) insight('Home PV Control', 'PV limit', `${reason}; ${changedFinalRestore.join(', ')}`);
        if (notify) {
            notification = {
                title: 'PV restored',
                message:
`Hidden PV Reveal final restore.

Reason: ${reason}

Market/export price: ${formatNotificationPrice(market)} €/kWh
PV power: ${pvPower} W
Grid power: ${grid} W

Inverters changed: ${calls.length}`
            };
        }
    } else if (pvAction === 'restore') {
        let changedRestore = [];
        for (const inv of inverters) {
            if (inverterWriteRequired(inv.current, inv.full_power, 5)) {
                calls.push(serviceMsg('number', 'set_value', { value: inv.full_power }, { entity_id: inv.limit_entity }));
                changedRestore.push(`${inv.name} ${inv.current}→${inv.full_power}W`);
            }
        }
        if (changedRestore.length > 0) insight('Home PV Control', 'Restore', `${reason}; ${changedRestore.join(', ')}`);
        if (notify) {
            notification = {
                title: 'PV restored',
                message:
`PV restored to full power.

Reason: ${reason}

Market/export price: ${formatNotificationPrice(market)} €/kWh
PV power: ${pvPower} W
Grid power: ${grid} W

Inverters changed: ${calls.length}`
            };
        }
    } else if (pvAction === 'adjust') {
        let changedAdjust = [];
        for (const t of targets) {
            if (t.changed) {
                calls.push(serviceMsg('number', 'set_value', { value: t.target }, { entity_id: t.entity }));
                changedAdjust.push(`${t.name} ${t.current}→${t.target}W`);
            }
        }
        if (hiddenPvRevealResumed && previousRevealPauseReason === 'battery_not_charging') {
            insight('Home PV Control', 'Hidden PV Reveal', 'Battery charging recovered; reveal resumed.');
        } else if (hiddenPvRevealResumed && previousRevealPauseReason === 'low_stability') {
            insight('Home PV Control', 'Hidden PV Reveal', 'PV response recovered; reveal resumed.');
        }
        if (changedAdjust.length > 0 && revealHiddenPv) {
            flow.set('homePvControlLastHiddenPvReveal', {
                pending: true,
                evaluated: false,
                pv_power: pvPower,
                pv_timestamp_ms: entityTimestampMs(pvPowerEntity),
                grid_power: grid,
                grid_timestamp_ms: entityTimestampMs(gridEntity),
                target_grid: exportTarget,
                battery_charge_power: Math.max(0, -selectedBatteryPowerTotal),
                battery_power_timestamp_ms: currentBatteryPowerTimestampMs,
                battery_soc: selectedBatteryChargingSoc,
                increase: revealIncrease,
                target_total: targetTotal,
                current_limit_total: currentLimitTotal,
                pv_availability_ratio: currentLimitTotal > 0
                    ? (pvPower >= (currentLimitTotal - Math.max(deadband, 50))
                        ? 1
                        : clamp(pvPower / currentLimitTotal, 0, 1))
                    : 0,
                achievable_increase: Math.max(0, Math.min(
                    revealIncrease,
                    revealIncrease * (
                        currentLimitTotal > 0
                            ? (pvPower >= (currentLimitTotal - Math.max(deadband, 50))
                                ? 1
                                : clamp(pvPower / currentLimitTotal, 0, 1))
                            : 0
                    )
                )),
                requested_limits: targets
                    .filter(target => target.changed)
                    .map(target => ({ entity: target.entity, value: target.target })),
                ts: now
            });
        }
        if (changedAdjust.length > 0) {
            if (revealHiddenPv) {
                insight(
                    'Home PV Control',
                    'Hidden PV Reveal',
                    `${reason}; reveal +${revealIncrease}W → ${targetTotal}W. ${changedAdjust.join(', ')}`
                );
            } else {
                insight(
                    'Home PV Control',
                    'PV limit',
                    `${reason}; PV → ${targetTotal}W. ${changedAdjust.join(', ')}`
                );
            }
        }
        if (notify) {
            notification = {
                title: 'PV dynamically adjusted',
                message:
`PV dynamically adjusted.

Reason: ${reason}

Market/export price: ${formatNotificationPrice(market)} €/kWh
PV power: ${pvPower} W
Grid power: ${grid} W

Target total PV limit: ${targetTotal} W
Inverters changed: ${calls.length}`
            };
        }
    }

    flow.set('homePvControlRevealResponseHistory', revealResponseHistory.slice(-3));
    flow.set('homePvControlRevealStabilityScore', Math.round(revealStabilityScore));
    if (hiddenPvRevealNoPvResponse) {
        flow.set('homePvControlLastNoPvResponsePause', {
            active: true,
            pv_power: pvPower,
            ts: now
        });
    } else if (sunRecoveryDetected || revealHiddenPv || !controlHbc || wantsMinimumPv) {
        flow.set('homePvControlLastNoPvResponsePause', null);
        if (sunRecoveryDetected) {
            flow.set('homePvControlRevealResponseHistory', []);
            flow.set('homePvControlRevealStabilityScore', Math.round(revealStabilityScore));
            revealResponseHistory = [];
            revealPoorResponseCount = 0;
        }
    }

    // Keep the last reveal observation until the next evaluation can verify real PV response.
    // Clear it only when another PV mode takes over or a non-reveal adjustment is made.
    if (
        !controlHbc ||
        wantsMinimumPv ||
        ['minimum', 'restore', 'final_restore'].includes(pvAction) ||
        (pvAction === 'adjust' && !revealHiddenPv)
    ) {
        flow.set('homePvControlLastHiddenPvReveal', null);
    }


    // Publish inverter diagnostics after the action decision. Calculated targets
    // remain informational; requested targets and write flags represent real calls.
    const diagnosticTargetsByEntity = new Map(targets.map(t => [t.entity, t]));
    const requestedTargetFor = inv => {
        if (pvAction === 'minimum') return inv.minimum_power;
        if (pvAction === 'restore' || pvAction === 'final_restore') return inv.full_power;
        if (pvAction === 'adjust') {
            const target = diagnosticTargetsByEntity.get(inv.limit_entity);
            return target ? target.target : null;
        }
        return null;
    };
    flow.set('homePvControlInverterDiagnostics', {
        ts: now,
        action: pvAction,
        requestedTotal: calls.length > 0
            ? inverters.reduce((sum, inv) => {
                const requested = requestedTargetFor(inv);
                return sum + (Number.isFinite(Number(requested)) ? Number(requested) : Number(inv.current || 0));
            }, 0)
            : null,
        achievedTargetTotal: targets.reduce((sum, t) => sum + t.target, 0),
        unavailable: unavailableInverters.map(inv => ({
            name: inv.name,
            entity: inv.limit_entity,
            reason: 'live limit unavailable'
        })),
        inverters: inverters.map(inv => {
            const calculated = diagnosticTargetsByEntity.get(inv.limit_entity);
            const requested = requestedTargetFor(inv);
            const writeRequired = calls.some(call =>
                call && call.payload && call.payload.target &&
                call.payload.target.entity_id === inv.limit_entity
            );
            return {
                name: inv.name,
                entity: inv.limit_entity,
                current: inv.current,
                calculatedTarget: calculated ? calculated.target : null,
                requestedTarget: writeRequired ? requested : null,
                difference: writeRequired && Number.isFinite(Number(requested))
                    ? Math.round(Number(requested) - Number(inv.current))
                    : null,
                minimum: inv.minimum_power,
                maximum: inv.full_power,
                clamped: calculated ? calculated.clamped === true : false,
                writeRequired,
                action: writeRequired ? pvAction : 'none'
            };
        })
    });

    if (calls.length > 0) {
        outputs[0] = calls;

        const requestedWrites = calls
            .map(call => {
                const payload = call && call.payload ? call.payload : {};
                const entity = payload.target && payload.target.entity_id;
                const value = payload.data ? Number(payload.data.value) : NaN;
                return {
                    entity: typeof entity === 'string' ? entity : '',
                    value
                };
            })
            .filter(item => validEntity(item.entity) && Number.isFinite(item.value));

        if (requestedWrites.length > 0) {
            pendingWriteRequest = {
                requested: requestedWrites,
                requested_ts: now,
                checked: false,
                action: pvAction
            };
        }

        if (['adjust', 'minimum', 'restore', 'final_restore'].includes(pvAction)) {
            flow.set('homePvControlLastPvWriteMs', now);
            flow.set('homePvControlCooldownUntilMs', now + cooldownMs);
            cooldownActiveNow = cooldownMs > 0;
            if (cooldownMs > 0) {
                const cooldownDate = new Date(now + cooldownMs);
                const cooldownUntilText = `${String(cooldownDate.getHours()).padStart(2, '0')}:${String(cooldownDate.getMinutes()).padStart(2, '0')}:${String(cooldownDate.getSeconds()).padStart(2, '0')}`;
                insight('Home PV Control', 'Cooldown', `Active (${cooldownSeconds}s); next change after ${cooldownUntilText}`);
            }
        }
    }

    // Battery strategy switching via HBC strategy selector.
    if (controlHbc) {
        // Entry thresholds react immediately. Hysteresis is applied only when
        // leaving the active HBC price mode. Negative all-in-price mode remains
        // independent and always uses the exact all-in <= 0 boundary.
        const expensiveEnter = expensivePrice;
        const expensiveExit = expensivePrice - strategyHysteresis;

        const wantsCharge =
            allInValid &&
            chargeStrategy &&
            (
                allIn <= chargeEnter ||
                (currentStrategy === chargeStrategy && allIn <= chargeExit)
            );

        const wantsExpensive =
            allInValid &&
            expensiveStrategy &&
            (
                allIn >= expensiveEnter ||
                (currentStrategy === expensiveStrategy && allIn >= expensiveExit)
            );

        const wantsBalanced = allInValid && !wantsCharge && !wantsExpensive;

        if (wantsCharge && currentStrategy !== chargeStrategy) {
            batteryOption = chargeStrategy;
        } else if (wantsExpensive && currentStrategy !== expensiveStrategy) {
            batteryOption = expensiveStrategy;
        } else if (wantsBalanced && balancedStrategy && currentStrategy !== balancedStrategy) {
            batteryOption = balancedStrategy;
        }

        if (batteryOption && hbcStrategyOptions.includes(batteryOption)) {
            insight('Battery Strategy', 'Selected', `${currentStrategy} → ${batteryOption}`);
            outputs[6] = serviceMsg('input_select', 'select_option', { option: batteryOption }, { entity_id: hbcStrategyEntity });
            if (notify) {
                let batteryReason = '';
                if (batteryOption === chargeStrategy) {
                    const trigger = allIn <= chargeEnter
                        ? `at or below charge entry threshold ${formatNotificationPrice(chargeEnter)}`
                        : `inside the charge hold band up to ${formatNotificationPrice(chargeExit)}`;
                    batteryReason = `all-in price ${formatNotificationPrice(allIn)} €/kWh is ${trigger} €/kWh.`;
                } else if (batteryOption === expensiveStrategy) {
                    const trigger = allIn >= expensiveEnter
                        ? `at or above expensive entry threshold ${formatNotificationPrice(expensiveEnter)}`
                        : `inside the expensive hold band down to ${formatNotificationPrice(expensiveExit)}`;
                    batteryReason = `all-in price ${formatNotificationPrice(allIn)} €/kWh is ${trigger} €/kWh.`;
                } else {
                    batteryReason = `all-in price ${formatNotificationPrice(allIn)} €/kWh is in the balanced price zone.`;
                }
                notificationCalls.push(serviceMsg('persistent_notification', 'create', {
                    notification_id: 'battery_ems_status',
                    title: 'Battery strategy changed',
                    message: `Battery strategy changed to ${batteryOption}.\n\nReason: ${batteryReason}\n\nPrevious strategy: ${currentStrategy}`
                }, {}));
            }
        }
    }
}

// Do not log cooldown-finished entries in Insights; this keeps the history focused on actions.
// The first evaluation after cooldown expiry may already make a new PV decision.
flow.set('homePvControlCooldownActive', cooldownActiveNow);
if (cooldownJustFinished) {
    flow.set('homePvControlCooldownUntilMs', 0);
}

// Track hidden-PV reveal state so Insights only logs pause/resume/completed changes.
flow.set('homePvControlHiddenPvRevealPaused', hiddenPvRevealPaused);
flow.set('homePvControlRevealPauseReason', revealPauseReason);
flow.set('homePvControlHbcBatteryCountFallbackActive', hbcBatteryCountFallbackActive);
if (!controlHbc || wantsMinimumPv) {
    flow.set('homePvControlHiddenPvRevealActive', false);
    flow.set('homePvControlHiddenPvRevealCompleted', false);
} else if (hiddenPvRevealCompleted) {
    flow.set('homePvControlHiddenPvRevealActive', false);
    flow.set('homePvControlHiddenPvRevealCompleted', true);
} else if (revealHiddenPv) {
    flow.set('homePvControlHiddenPvRevealActive', true);
    flow.set('homePvControlHiddenPvRevealCompleted', false);
}

// Helper/status updates. Publish only changed values to avoid unnecessary
// Home Assistant state changes, recorder writes, and downstream triggers.
// Output 8 carries changed HBC status, model-ownership, learning, and diagnostic helper updates.
const statusValue = String(status).slice(0, 255);
const reasonValue = String(reason).slice(0, 255);
outputs[1] = strEntity('input_text.hpvc_status', '') !== statusValue
    ? serviceMsg('input_text', 'set_value', { value: statusValue }, { entity_id: 'input_text.hpvc_status' })
    : null;
outputs[2] = strEntity('input_text.hpvc_reason', '') !== reasonValue
    ? serviceMsg('input_text', 'set_value', { value: reasonValue }, { entity_id: 'input_text.hpvc_reason' })
    : null;
// Last action must also refresh when a new control decision keeps the same broad
// status but changes its reason/target (for example repeated PV-limit adjustments).
const lastActionSignature = `${statusValue}|${reasonValue}`;
const previousLastActionSignature = String(flow.get('homePvControlLastActionSignature') || '');
if (previousLastActionSignature !== lastActionSignature) {
    outputs[3] = serviceMsg('input_text', 'set_value', {
        value: (new Date().toLocaleString() + ' - ' + statusValue).slice(0, 255)
    }, { entity_id: 'input_text.hpvc_last_action' });
    flow.set('homePvControlLastActionSignature', lastActionSignature);
}

// Current-calendar-day accuracy averages.
// Target accuracy is sampled on every evaluation while PV is limited.
// Reveal accuracy is sampled only when a real reveal response was evaluated.
const accuracyDateKey = (() => {
    const d = new Date(now);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
})();

const accuracyEligibilitySchema = 5;
let dailyAccuracy = flow.get('homePvControlDailyAccuracy');
if (
    !dailyAccuracy ||
    Number(dailyAccuracy.eligibilitySchema || 0) !== accuracyEligibilitySchema ||
    dailyAccuracy.date !== accuracyDateKey ||
    !Number.isFinite(Number(dailyAccuracy.targetSum)) ||
    !Number.isFinite(Number(dailyAccuracy.targetCount)) ||
    !Number.isFinite(Number(dailyAccuracy.revealWeightedSum)) ||
    !Number.isFinite(Number(dailyAccuracy.revealWeightTotal)) ||
    !Number.isFinite(Number(dailyAccuracy.revealCount))
) {
    dailyAccuracy = {
        eligibilitySchema: accuracyEligibilitySchema,
        date: accuracyDateKey,
        targetSum: 0,
        targetCount: 0,
        revealWeightedSum: 0,
        revealWeightTotal: 0,
        revealCount: 0,
        targetFactorLoss: { control: 0, load: 0, pv: 0, other: 0 },
        revealFactorLoss: { interrupted: 0, overshoot: 0, limited: 0, other: 0 },
        previousTargetSample: null
    };
}

// Migrate compatible same-day context without losing valid samples.
if (!dailyAccuracy.targetFactorLoss || typeof dailyAccuracy.targetFactorLoss !== 'object') {
    dailyAccuracy.targetFactorLoss = { control: 0, load: 0, pv: 0, other: 0 };
}
if (!dailyAccuracy.revealFactorLoss || typeof dailyAccuracy.revealFactorLoss !== 'object') {
    dailyAccuracy.revealFactorLoss = { interrupted: 0, overshoot: 0, limited: 0, other: 0 };
}
if (!Object.prototype.hasOwnProperty.call(dailyAccuracy, 'previousTargetSample')) {
    dailyAccuracy.previousTargetSample = null;
}

const pvLimitedForAccuracy =
    inverters.some(inv => inv.current < (inv.full_power - deadband));
const currentLimitTotalForAccuracy =
    inverters.reduce((sum, inv) => sum + Number(inv.current || 0), 0);
const accuracyBindingMargin = Math.max(deadband, 50);
// Score target accuracy only when the active inverter limits appear to be
// physically binding. A limit below maximum does not curtail PV during low sun.
const limitAppearsBindingForAccuracy =
    currentLimitTotalForAccuracy > 0 &&
    pvPower >= (currentLimitTotalForAccuracy - accuracyBindingMargin);
const targetAccuracyEligible =
    enabled &&
    stateIsNumeric(gridEntity) &&
    stateIsNumeric(pvPowerEntity) &&
    thresholdConfigurationValid &&
    pvLimitedForAccuracy &&
    limitAppearsBindingForAccuracy &&
    !wantsMinimumPv &&
    !persistentNightRestore &&
    !cooldownActiveNow &&
    !['Disabled', 'Waiting for inputs', 'Waiting for restore', 'Inputs unavailable', 'Configuration error'].includes(status);

if (targetAccuracyEligible) {
    // The configured deadband is the accepted target range and should score 100%.
    // Only error outside that range reduces the sample.
    const targetError = Math.abs(grid - exportTarget);
    const errorOutsideDeadband = Math.max(0, targetError - deadband);
    const accuracyScale = Math.max(
        Math.abs(exportStart - exportTarget) - deadband,
        deadband,
        1
    );
    const targetAccuracySample = Math.max(
        0,
        Math.min(
            100,
            100 - (errorOutsideDeadband / accuracyScale * 100)
        )
    );
    dailyAccuracy.targetSum += targetAccuracySample;
    dailyAccuracy.targetCount += 1;

    // Attribute this sample's own loss instead of distributing the complete daily
    // loss from sparse Insight counts. The four factor totals therefore always
    // describe the same samples used to calculate Daily Target Accuracy.
    const targetSampleLoss = Math.max(0, 100 - targetAccuracySample);
    if (targetSampleLoss > 0) {
        const previousSample = dailyAccuracy.previousTargetSample;
        let targetFactor = 'other';

        if (previousSample && Number.isFinite(Number(previousSample.ts))) {
            const elapsed = now - Number(previousSample.ts);
            const previousLimit = Number(previousSample.limit);
            const currentLimit = inverters.reduce((sum, inv) => sum + Number(inv.current || 0), 0);
            const limitChange = Number.isFinite(previousLimit) ? currentLimit - previousLimit : 0;
            const pvChange = pvPower - Number(previousSample.pv || 0);
            const previousHouseLoad = Number(previousSample.houseLoad);
            const currentHouseLoad = pvPower + grid;
            const houseLoadChange = Number.isFinite(previousHouseLoad)
                ? currentHouseLoad - previousHouseLoad
                : 0;
            const changeThreshold = Math.max(deadband, 25);
            const recentWindowMs = Math.max(120000, cooldownMs * 3);
            const lastPvWriteMs = Number(flow.get('homePvControlLastPvWriteMs') || 0);
            const recentControllerWrite =
                lastPvWriteMs > 0 &&
                (now - lastPvWriteMs) <= recentWindowMs;
            const atEffectiveMinimum = inverters.length > 0 && inverters.every(
                inv => inv.current <= (inv.minimum_power + deadband)
            );
            const atEffectiveMaximum = inverters.length > 0 && inverters.every(
                inv => inv.current >= (inv.full_power - deadband)
            );
            const controlStateExplainsHold =
                recentControllerWrite ||
                atEffectiveMinimum ||
                atEffectiveMaximum ||
                pvAction !== 'none' ||
                status === 'Limiting' ||
                status === 'Restoring' ||
                status === 'Monitoring' ||
                Math.abs(limitChange) >= changeThreshold;

            // A recent or still-visible inverter adjustment is a controller-response
            // effect, even when the next sample is taken after cooldown has expired.
            if (elapsed <= recentWindowMs && controlStateExplainsHold) {
                targetFactor = 'control';
            // Estimate house load as PV + grid (grid is positive import and negative
            // export). This separates genuine load movement from simultaneous PV movement.
            } else if (
                elapsed <= 120000 &&
                Math.abs(houseLoadChange) >= changeThreshold &&
                Math.abs(houseLoadChange) >= Math.abs(pvChange) * 0.6
            ) {
                targetFactor = 'load';
            // With stable inverter limits and no dominant load step, meaningful PV
            // movement is attributed to changing PV availability.
            } else if (
                elapsed <= 120000 &&
                Math.abs(pvChange) >= changeThreshold
            ) {
                targetFactor = 'pv';
            // A stable but off-target sample while active limiting is still meaningful:
            // the configured deadband, thresholds, inverter resolution or plant response
            // is holding the result. Attribute that expected behavior to control response
            // rather than the generic fallback.
            } else if (
                elapsed <= recentWindowMs &&
                Math.abs(grid - exportTarget) > deadband
            ) {
                targetFactor = 'control';
            }
        } else {
            // The first eligible sample has no comparison history. Because it is taken
            // only while an inverter limit is physically binding, its loss is best
            // described as control response rather than an unknown external cause.
            targetFactor = 'control';
        }

        dailyAccuracy.targetFactorLoss[targetFactor] =
            Number(dailyAccuracy.targetFactorLoss[targetFactor] || 0) + targetSampleLoss;
    }

    dailyAccuracy.previousTargetSample = {
        ts: now,
        grid,
        pv: pvPower,
        houseLoad: pvPower + grid,
        limit: inverters.reduce((sum, inv) => sum + Number(inv.current || 0), 0),
        status,
        action: pvAction
    };
}

if (
    typeof revealEffectiveness === 'number' &&
    Number.isFinite(revealEffectiveness)
) {
    const revealAccuracySample = Math.max(0, Math.min(100, revealEffectiveness));
    const revealSampleWeight = Math.max(
        deadband,
        Number(revealAccuracyWeight) ||
        Number((flow.get('homePvControlLastHiddenPvReveal') || {}).increase) ||
        deadband
    );
    dailyAccuracy.revealWeightedSum += revealAccuracySample * revealSampleWeight;
    dailyAccuracy.revealWeightTotal += revealSampleWeight;
    dailyAccuracy.revealCount += 1;

    // Factor loss uses the same watt weighting as the daily score.
    const revealSampleLoss =
        Math.max(0, 100 - revealAccuracySample) * revealSampleWeight;
    if (revealSampleLoss > 0) {
        const evaluatedReveal = flow.get('homePvControlLastHiddenPvReveal') || {};
        const requestedReveal = Math.max(1, Number(evaluatedReveal.increase) || 0);
        const requiredResponse = Math.max(deadband, requestedReveal * 0.25);
        const latestRevealResponse = Array.isArray(revealResponseHistory) && revealResponseHistory.length > 0
            ? revealResponseHistory[revealResponseHistory.length - 1]
            : {};
        const evaluatedOvershoot = latestRevealResponse.overshot_target === true;
        const targetResponseAccuracy = Number.isFinite(Number(latestRevealResponse.target_effectiveness))
            ? Number(latestRevealResponse.target_effectiveness)
            : revealAccuracySample;
        const evaluationInterrupted =
            latestRevealResponse.interrupted === true ||
            hiddenPvRevealPaused ||
            ['restore', 'minimum'].includes(pvAction);
        let revealFactor = 'other';

        // Every scored loss must be attributed to the same physical outcome that
        // reduced the sample. A partial but otherwise valid response is Limited PV
        // response even when it still scored 70–99%; it must not fall into Other.
        if (evaluatedOvershoot) {
            revealFactor = 'overshoot';
        } else if (evaluationInterrupted) {
            revealFactor = 'interrupted';
        } else if (
            targetResponseAccuracy < 100 ||
            hiddenPvRevealBatteryTaper ||
            hiddenPvRevealNoPvResponse ||
            revealBatteryChargeResponse < Math.max(25, requestedReveal * 0.20) ||
            Number(latestRevealResponse.response || 0) < requiredResponse
        ) {
            revealFactor = 'limited';
        }

        dailyAccuracy.revealFactorLoss[revealFactor] =
            Number(dailyAccuracy.revealFactorLoss[revealFactor] || 0) + revealSampleLoss;
    }
}

flow.set('homePvControlDailyAccuracy', dailyAccuracy);

const dailyTargetAccuracy =
    dailyAccuracy.targetCount > 0
        ? Math.round(dailyAccuracy.targetSum / dailyAccuracy.targetCount)
        : null;
const dailyRevealAccuracy =
    dailyAccuracy.revealWeightTotal > 0
        ? Math.round(dailyAccuracy.revealWeightedSum / dailyAccuracy.revealWeightTotal)
        : null;

let lastCalc = {
    cd: cooldownActiveNow,
    lim: inverters.some(inv => inv.current < (inv.full_power - deadband)),
    t: Math.round(targetTotal),
    g: Math.round(grid),
    p: Math.round(pvPower),
    bh: Math.round(effectiveBatteryHeadroom),
    tol: Math.round(targetTolerance),
    mg: Math.round(exportTargetMargin),
    hid: Math.round(hiddenPvRemaining),
    rev: Math.round(adaptiveRevealIncrease),
    sc: Math.round(revealStabilityScore),
    ef: revealEffectiveness,
    ae: revealAbsorptionEffectiveness,
    da: dailyTargetAccuracy,
    ra: dailyRevealAccuracy,
    pr: revealPoorResponseCount,
    sun: sunRecoveryDetected,
    n: nightRestoreCondition,
    nr: persistentNightRestore,
    nm: sunAvailable ? 's' : 'p',
    sa: sunAvailable,
    ss: sunAvailable ? (sunState === 'below_horizon' ? 'b' : 'a') : 'x',
    cfg: thresholdConfigurationValid,
    gd: hiddenPvRevealNoPvResponse
};
let lastCalcJson = JSON.stringify(lastCalc);
if (lastCalcJson.length > 255) {
    lastCalc = {
        cd: lastCalc.cd,
        lim: lastCalc.lim,
        t: lastCalc.t,
        g: lastCalc.g,
        p: lastCalc.p,
        da: lastCalc.da,
        ra: lastCalc.ra,
        cfg: lastCalc.cfg,
        err: 'diagnostic_payload_reduced'
    };
    lastCalcJson = JSON.stringify(lastCalc);
    insight('Home PV Control', 'Debug', 'Compact debug payload exceeded 255 characters; reduced valid JSON stored.');
}
outputs[4] = serviceMsg('input_text', 'set_value', { value: lastCalcJson }, { entity_id: 'input_text.hpvc_last_targets_json' });

if (strEntity('input_text.hpvc_hbc_status', '') !== hbcStatusText) {
    const hbcStatusMsg = serviceMsg('input_text', 'set_value', { value: hbcStatusText.slice(0,255) }, { entity_id: 'input_text.hpvc_hbc_status' });
    appendOutputMessage(8, hbcStatusMsg);
}
const hbcPriceModelPayload = {
    r: hbcAllInModel.ready,
    a: Number(hbcAllInModel.slope.toFixed(6)),
    b: Number(hbcAllInModel.intercept.toFixed(6)),
    n: hbcAllInModel.count,
    u: Number(hbcAllInModel.learned_at || 0),
    v: Number(hbcAllInModel.last_validated || 0),
    e: Number.isFinite(hbcAllInModel.validation_error)
        ? Number(hbcAllInModel.validation_error.toFixed(6))
        : null
};
const hbcPriceModelJson = JSON.stringify(hbcPriceModelPayload);
if (strEntity('input_text.hpvc_hbc_price_model_json', '') !== hbcPriceModelJson) {
    appendOutputMessage(8, serviceMsg('input_text', 'set_value',
        { value: hbcPriceModelJson.slice(0, 255) },
        { entity_id: 'input_text.hpvc_hbc_price_model_json' }
    ));
}

// Store the exact configured sensor IDs separately so model ownership remains
// collision-free without consuming the compact model JSON helper. Write the model
// first, then its owners, so a sensor change cannot expose a stale ready model.
if (strEntity('input_text.hpvc_hbc_price_model_market_entity', '') !== marketEntity) {
    appendOutputMessage(8, serviceMsg('input_text', 'set_value',
        { value: String(marketEntity || '').slice(0, 255) },
        { entity_id: 'input_text.hpvc_hbc_price_model_market_entity' }
    ));
}
if (strEntity('input_text.hpvc_hbc_price_model_all_in_entity', '') !== allInEntity) {
    appendOutputMessage(8, serviceMsg('input_text', 'set_value',
        { value: String(allInEntity || '').slice(0, 255) },
        { entity_id: 'input_text.hpvc_hbc_price_model_all_in_entity' }
    ));
}

// Persist only the compact state needed to resume learning or monthly validation.
// The full rolling sample list remains in flow context. Repeated Market prices are
// grouped and averaged before the four lowest and four highest distinct points are saved.
const encodePair = sample => [
    Math.round(Number(sample.x) * 10000),
    Math.round(Number(sample.y) * 10000)
];
let hbcLearningPayload = {};
if (!hbcAllInModel.ready && Array.isArray(hbcAllInModel.samples) && hbcAllInModel.samples.length > 0) {
    const progressGroups = new Map();
    for (const sample of hbcAllInModel.samples) {
        const key = Math.round(Number(sample.x) * 10000);
        if (!Number.isFinite(key) || !Number.isFinite(Number(sample.y))) continue;
        const group = progressGroups.get(key) || { x: key / 10000, ySum: 0, count: 0 };
        group.ySum += Number(sample.y);
        group.count += 1;
        progressGroups.set(key, group);
    }
    const orderedDistinct = [...progressGroups.values()]
        .map(group => ({ x: group.x, y: group.ySum / group.count }))
        .sort((a, b) => a.x - b.x);
    hbcLearningPayload = {
        t: 'l',
        s: Number(hbcAllInModel.collection_started || now),
        n: Number(hbcAllInModel.count || hbcAllInModel.samples.length),
        p: encodePair(hbcAllInModel.samples[hbcAllInModel.samples.length - 1]),
        l: orderedDistinct.slice(0, 4).map(encodePair),
        h: orderedDistinct.slice(-4).map(encodePair)
    };
} else if (hbcAllInModel.ready && Array.isArray(hbcAllInModel.validation_samples) && hbcAllInModel.validation_samples.length > 0) {
    hbcLearningPayload = {
        t: 'v',
        s: Number(hbcAllInModel.validation_samples[0].ts || now),
        q: hbcAllInModel.validation_samples.slice(-3).map(encodePair)
    };
}
let hbcLearningJson = JSON.stringify(hbcLearningPayload);
if (hbcLearningJson.length > 255) {
    // This should not normally occur with the compact integer representation.
    // Preserve the newest validation pairs, or the most extreme training pairs.
    if (hbcLearningPayload.t === 'v') {
        hbcLearningPayload.q = hbcLearningPayload.q.slice(-2);
    } else if (hbcLearningPayload.t === 'l') {
        hbcLearningPayload.l = hbcLearningPayload.l.slice(0, 3);
        hbcLearningPayload.h = hbcLearningPayload.h.slice(-3);
    }
    hbcLearningJson = JSON.stringify(hbcLearningPayload);
}
if (strEntity('input_text.hpvc_hbc_price_learning_json', '{}') !== hbcLearningJson) {
    appendOutputMessage(8, serviceMsg('input_text', 'set_value',
        { value: hbcLearningJson.slice(0, 255) },
        { entity_id: 'input_text.hpvc_hbc_price_learning_json' }
    ));
}
// Current-day Insight log plus the latest 20 entries for the Home Assistant dashboard.
// Configure Node-RED file-backed context storage if the rolling log must survive a Node-RED restart.

const pendingWrite = flow.get('homePvControlPendingWriteVerification');
if (pendingWrite && pendingWrite.checked !== true && Array.isArray(pendingWrite.requested)) {
    const age = now - Number(pendingWrite.requested_ts || 0);
    if (age >= Math.max(5000, cooldownSeconds * 1000)) {
        const tolerance = Math.max(2, Math.min(deadband, 10));
        const results = pendingWrite.requested.map(item => {
            const actual = numEntity(item.entity, NaN);
            return { ...item, actual, ok: Number.isFinite(actual) && Math.abs(actual - item.value) <= tolerance };
        });
        const failed = results.filter(item => !item.ok);
        if (failed.length === 0) {
            // Successful writes are confirmed internally without adding a routine Insight.
            flow.set('homePvControlPendingWriteVerification', { ...pendingWrite, checked: true, confirmed: true, checked_ts: now, results });
            flow.set('homePvControlLastInverterWriteResults', { ts: now, action: pendingWrite.action, results });
        } else if (pendingWriteRequest) {
            // A newer HPVC write supersedes the previous target. Do not surface this as a
            // failed write: fast control adjustments can legitimately replace a target
            // before the non-persistent inverter number entities report that exact value.
            flow.set('homePvControlPendingWriteVerification', {
                ...pendingWrite,
                checked: true,
                confirmed: false,
                superseded: true,
                checked_ts: now
            });
        } else if (age >= Math.max(30000, cooldownSeconds * 2000)) {
            insight('Home PV Control', 'Write warning', `Not confirmed within the verification timeout: ${failed.map(item => `${item.entity} requested ${item.value}W, actual ${Number.isFinite(item.actual) ? Math.round(item.actual) + 'W' : 'unavailable'}`).join(', ')}`);
            flow.set('homePvControlPendingWriteVerification', { ...pendingWrite, checked: true, confirmed: false, superseded: false, checked_ts: now, results });
            flow.set('homePvControlLastInverterWriteResults', { ts: now, action: pendingWrite.action, results });
        }
    }
}

// Store the write issued during this evaluation only after the previous pending
// write has been checked above. This prevents a fresh command from hiding a
// confirmation or warning for the preceding command.
if (pendingWriteRequest && Array.isArray(pendingWriteRequest.requested) && pendingWriteRequest.requested.length > 0) {
    flow.set('homePvControlPendingWriteVerification', pendingWriteRequest);
}

// Detect genuine controller hunting while excluding expected HBC battery transitions.
// A full/charging/strategy transition starts a new control situation, so previous
// reversals are discarded and adjustment directions are ignored for 60 seconds.
const batteryControlSignature = [
    controlHbc ? 'hbc_on' : 'hbc_off',
    selectedBatteryFull ? 'full' : 'not_full',
    selectedBatteryIsCharging ? 'charging' : 'not_charging',
    controlHbc ? strEntity(hbcStrategyEntity, '') : ''
].join('|');
const previousBatteryControlSignature = String(flow.get('homePvControlBatteryControlSignature') || '');
let lastBatteryControlTransition = Number(flow.get('homePvControlLastBatteryControlTransition') || 0);
if (previousBatteryControlSignature && previousBatteryControlSignature !== batteryControlSignature) {
    lastBatteryControlTransition = now;
    flow.set('homePvControlLastBatteryControlTransition', now);
    flow.set('homePvControlDirectionHistory', []);
}
flow.set('homePvControlBatteryControlSignature', batteryControlSignature);

const batteryTransitionGraceActive = lastBatteryControlTransition > 0 && (now - lastBatteryControlTransition) < 60000;
const actionCurrentLimitTotal = inverters.reduce((sum, inv) => sum + Number(inv.current || 0), 0);

// Count only actual dynamic adjustments. Restore/minimum actions and changes close
// to battery/HBC transitions are legitimate state changes, not oscillation.
if (pvAction === 'adjust' && !batteryTransitionGraceActive) {
    const direction = targetTotal > actionCurrentLimitTotal
        ? 'up'
        : (targetTotal < actionCurrentLimitTotal ? 'down' : 'hold');
    const controlMode = revealHiddenPv
        ? 'reveal'
        : (grid < exportStart ? 'limit' : (importRecalcActive ? 'recovery' : 'adjust'));
    let history = Array.isArray(flow.get('homePvControlDirectionHistory')) ? flow.get('homePvControlDirectionHistory') : [];
    history.push({ ts: now, direction, mode: controlMode, battery: batteryControlSignature });
    history = history
        .filter(item => now - Number(item.ts || 0) <= 120000 && item.battery === batteryControlSignature)
        .slice(-20);
    flow.set('homePvControlDirectionHistory', history);

    let reversals = 0;
    for (let i = 1; i < history.length; i++) {
        const previous = history[i - 1];
        const current = history[i];
        if (
            current.direction !== 'hold' &&
            previous.direction !== 'hold' &&
            current.direction !== previous.direction
        ) {
            reversals++;
        }
    }

    const lastWarning = Number(flow.get('homePvControlLastOscillationWarning') || 0);
    if (reversals >= 4 && now - lastWarning >= 300000) {
        insight('Home PV Control', 'Control warning', `Oscillation detected: ${reversals} unexplained PV direction reversals in 2 minutes; battery full/charging and HBC strategy transitions were excluded`);
        flow.set('homePvControlLastOscillationWarning', now);
    }
}

const insightDateKey = (() => {
    const d = new Date(now);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
})();

let insightLog = flow.get('hpvcInsightLog') || flow.get('hpvcDailyInsightLog');
if (!insightLog || !Array.isArray(insightLog.entries)) {
    insightLog = { date: insightDateKey, entries: [] };
} else if (!insightLog.date) {
    // Migrate an older rolling/current-day log without deleting today's entries.
    const todayEntries = insightLog.entries.filter(entry => {
        const ts = Number(entry?.ts);
        if (!Number.isFinite(ts)) return false;
        const d = new Date(ts);
        const entryDateKey =
            `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
