function escapeHtml(value) {
    return String(value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
}

function insightClass(line) {
    const text = String(line || '').toLowerCase();
    if (text.includes('| write warning |') || text.includes('| control warning |')) return 'warning';
    if (
        (text.includes('| master control |') || text.includes('| hbc control |')) &&
        text.includes('enabled')
    ) return 'control-on';
    if (
        (text.includes('| master control |') || text.includes('| hbc control |')) &&
        text.includes('disabled')
    ) return 'control-off';
    if (text.includes('| restore |')) return 'restore';
    if (text.includes('| cooldown |')) return 'cooldown';
    if (text.includes('| hidden pv reveal |') || text.includes('reveal')) return 'reveal';
    if (text.includes('| pv limit |')) return 'pv';
    return 'default';
}

function insightIcon(line) {
    const type = insightClass(line);
    if (type === 'warning') return '⚠️';
    if (type === 'control-on') return '●';
    if (type === 'control-off') return '○';
    if (type === 'restore') return '↻';
    if (type === 'cooldown') return '⏱';
    if (type === 'reveal') return '🔋';
    if (type === 'pv') return '☀️';
    return 'ℹ️';
}

