    .insight.control-off .insight-icon { color: var(--muted); }
    .insight.restore { border-left-color: var(--restore); }
    .insight.cooldown { border-left-color: var(--cooldown); }
    .insight.reveal { border-left-color: var(--reveal); }
    .insight.pv { border-left-color: var(--pv); }
    .insight-icon { font-size: 1.15rem; padding-top: 1px; }
    .insight-meta { display: flex; gap: 12px; flex-wrap: wrap; align-items: baseline; }
    .insight-meta span { color: var(--muted); font-size: .82rem; }
    .insight-meta strong { font-size: .85rem; text-transform: uppercase; letter-spacing: .04em; }
    .insight-message { margin-top: 5px; line-height: 1.45; }
    .insight-source { margin-top: 5px; color: var(--muted); font-size: .78rem; }
    .raw-report { display: none; }
    .quick-nav { display:flex; gap:8px; overflow-x:auto; scrollbar-width:thin; padding:4px 0 10px; position:sticky; top:72px; z-index:8; background:linear-gradient(var(--bg) 82%, transparent); }
    .quick-nav a { flex:0 0 auto; color:var(--text); text-decoration:none; background:var(--panel-2); border:1px solid var(--line); border-radius:999px; padding:8px 11px; font-size:.78rem; }
    .mobile-card-list { display:none; gap:10px; }
    .mobile-data-card { background:linear-gradient(180deg,var(--panel-2),var(--panel)); border:1px solid var(--line); border-radius:16px; padding:14px; }
    .mobile-card-title { font-size:1rem; font-weight:800; margin-bottom:7px; }
    .mobile-kv { display:flex; justify-content:space-between; gap:14px; padding:9px 0; border-bottom:1px solid var(--line); align-items:baseline; }
    .mobile-kv:last-child { border-bottom:0; }
    .mobile-kv span { color:var(--muted); }
    .mobile-kv strong { text-align:right; overflow-wrap:anywhere; }
    .section-details > summary { list-style:none; cursor:pointer; }
    .section-details > summary::-webkit-details-marker { display:none; }
    .section-details > summary .section-title::after { content:'▾'; float:right; color:var(--muted); transition:transform .2s; }
    .section-details:not([open]) > summary .section-title::after { transform:rotate(-90deg); }
    .section-details[open] > summary { margin-bottom:12px; }
    @media (max-width: 760px) {
      .desktop-table { display:none; }
      .mobile-card-list { display:grid; }
      .quick-nav { top:64px; margin-left:-12px; margin-right:-12px; padding-left:12px; padding-right:12px; }
      .section { scroll-margin-top:120px; }
    }
    @media (max-width: 640px) {
      .shell { padding: 12px; }
      .topbar { align-items: flex-start; padding:10px 0; }
      .brand h1 { font-size: 1.25rem; }
      .brand p { font-size:.78rem; }
      button { white-space: nowrap; padding:9px 11px; font-size:.82rem; }
      th, td { padding: 11px 10px; }
      .insight { grid-template-columns: 30px 1fr; }
      .sensor-row { grid-template-columns: 1fr auto; gap: 6px 12px; align-items:start; }
      .sensor-row > strong { text-align:right; }
      .sensor-detail { grid-column: 1 / -1; text-align: left; font-size:.72rem; overflow-wrap:anywhere; }
      .detail-row, .metric-row { gap:10px; }
      .detail-row strong, .metric-row strong { max-width:56%; overflow-wrap:anywhere; }
    }
    @media print {
      @page { margin: 12mm; }
      html, body {
        background: var(--bg);
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
      }
      .shell { max-width: none; padding: 0; }
      .topbar {
        position: static;
        padding: 0 0 10px;
        background: none;
        backdrop-filter: none;
      }
      #download-report, #copy-status, .quick-nav { display: none !important; }
      .section { margin-top: 16px; }
      .section-title { margin-bottom: 8px; }
      .card, .battery-card, .insight, .table-wrap, .mobile-data-card,
      .accuracy-card, .detail-card, table, tr {
        break-inside: avoid;
        page-break-inside: avoid;
      }
      .section-details > summary, .section-title {
        break-after: avoid;
        page-break-after: avoid;
      }
      .card { padding: 13px; }
      .battery-card { padding: 13px; }
      .detail-row, .metric-row { padding: 8px 0; }
      th, td { padding: 9px 10px; }
      .insight { padding: 10px 11px; }
    }
  </style>
</head>
<body>
  <main class="shell">
    <header class="topbar">
      <div class="brand">
        <h1>HPVC report</h1>
        <p>${escapeHtml(generatedValue)} · v${escapeHtml(versionValue)}</p>
      </div>
      <div>
        <button id="download-report" type="button">Download report</button>
        <span id="copy-status" aria-live="polite"></span>
      </div>
    </header>

    <nav class="quick-nav" aria-label="Report sections">
      <a href="#status">Status</a><a href="#live">Live</a><a href="#decision">Decision</a><a href="#accuracy">Accuracy</a><a href="#inverters">Inverters</a><a href="#settings">Settings</a><a href="#hbc">Batteries</a><a href="#sensors">Sensors</a><a href="#insights">Insights</a>
    </nav>

    <section class="section" id="status">
      <h2 class="section-title">Executive summary</h2>
      <div class="card detail-card">${executiveRows}</div>
    </section>

    <section class="section" id="live">
      <h2 class="section-title">Live status</h2>
      <div class="cards">
        <article class="card"><div class="card-kicker">Grid</div><div class="card-value">${escapeHtml(reportModel.live.grid)}</div><div class="card-sub">Target ${escapeHtml(String(exportTargetNumber))} W</div></article>
        <article class="card"><div class="card-kicker">PV</div><div class="card-value">${escapeHtml(reportModel.live.pv)}</div><div class="card-sub">Current solar power</div></article>
        <article class="card"><div class="card-kicker">Market/export price</div><div class="card-value">${escapeHtml(reportModel.live.market)}</div><div class="card-sub">PV control price</div></article>
        <article class="card"><div class="card-kicker">All-in price</div><div class="card-value">${escapeHtml(reportModel.live.allIn)}</div><div class="card-sub">HBC strategy price</div></article>
      </div>
    </section>

    <section class="section" id="decision">
      <h2 class="section-title">Decision evaluation</h2>
      <div class="card detail-card">${decisionRowsHtml}</div>
    </section>

    <details class="section section-details" id="accuracy" open>
      <summary><h2 class="section-title">Today's accuracy</h2></summary>
      <div class="accuracy-grid">
        <article class="card accuracy-card">
          <div class="accuracy-icon">🎯</div>
          <div class="accuracy-title">Daily Target Accuracy</div>
          <div class="accuracy-score${targetAccuracyHasData ? '' : ' no-data'}">${escapeHtml(targetAccuracyValue)}</div>
          <div class="accuracy-subtitle">Average while PV was limited</div>
          <div class="accuracy-groups">
            ${targetAccuracyHasData ? `
            <div class="metric-heading">Estimated accuracy-loss factors</div>
            ${diagnosticRows(targetFactorRows)}
            ` : '<div class="no-data-note">No factor data collected today.</div>'}
          </div>
          <div class="accuracy-footer"><span>Daily average</span><span class="rating-pill">${escapeHtml(targetAccuracyRating)}</span></div>
        </article>
        <article class="card accuracy-card">
          <div class="accuracy-icon">🔋</div>
          <div class="accuracy-title">Daily Reveal Accuracy</div>
          <div class="accuracy-score${revealAccuracyHasData ? '' : ' no-data'}">${escapeHtml(revealAccuracyValue)}</div>
          <div class="accuracy-subtitle">Average while using Hidden PV</div>
          <div class="accuracy-groups">
            ${revealAccuracyHasData ? `
            <div class="metric-heading">Estimated accuracy-loss factors</div>
            ${diagnosticRows(revealFactorRows)}
            ` : '<div class="no-data-note">No factor data collected today.</div>'}
          </div>
          <div class="accuracy-footer"><span>Daily average</span><span class="rating-pill">${escapeHtml(revealAccuracyRating)}</span></div>
        </article>
      </div>
    </details>

    <details class="section section-details" id="inverters" open>
      <summary><h2 class="section-title">Inverters</h2></summary>
      <div class="table-wrap desktop-table">
        <table>
          <thead><tr><th>Inverter</th><th>Current limit</th><th>Maximum power</th><th>Minimum power</th><th>Calculated target</th><th>Requested target</th><th>Difference from target</th><th>At min/max</th><th>Write required</th><th>Last verification</th></tr></thead>
          <tbody>${inverterRows || '<tr><td colspan="10">No inverter data</td></tr>'}</tbody>
        </table>
      </div>
      <div class="mobile-card-list">${inverterMobileCards || '<article class="mobile-data-card">No inverter data</article>'}</div>
      <div class="card detail-card" style="margin-top:12px">
        <div class="card-kicker">Inverter diagnostics</div>
        ${inverterDiagnosticsRows}
      </div>
    </details>

    <details class="section section-details" id="settings" open>
      <summary><h2 class="section-title">Control settings</h2></summary>
      <div class="grid-3">
        <article class="card detail-card"><div class="card-kicker">Price strategy</div>${priceRows}</article>
        <article class="card detail-card"><div class="card-kicker">Power control</div>${powerRows}</article>
        <article class="card detail-card"><div class="card-kicker">Control tuning</div>${tuningRows}</article>
      </div>
    </details>

    <details class="section section-details" id="hbc" open>
      <summary><h2 class="section-title">HBC &amp; Hidden PV Reveal</h2></summary>
      <div class="card detail-card">
        <div class="detail-row">
          <span>HBC status</span>
          <strong>${escapeHtml(hbcStatusDisplay)}</strong>
        </div>
      </div>
      ${hbcDetected ? `
      <div class="table-wrap desktop-table" style="margin-top:12px">
        <table>
          <thead>
            <tr>
              <th>Battery</th>
              <th>Status</th>
              <th>SOC</th>
              <th>Actual power</th>
              <th>Max charge power</th>
              <th>Raw charger headroom</th>
              <th>Current reveal allowance</th>
              <th>Telemetry</th>
              <th>Reason</th>
            </tr>
          </thead>
          <tbody>${batteryRows || '<tr><td colspan="9">No active battery data</td></tr>'}</tbody>
        </table>
      </div>
      <div class="mobile-card-list" style="margin-top:12px">${batteryMobileCards || '<article class="mobile-data-card">No active battery data</article>'}</div>
      <div class="card detail-card" style="margin-top:12px">${revealDiagnostics}</div>
      ` : ''}
    </details>

    <details class="section section-details" id="sensors" open>
      <summary><h2 class="section-title">Sensor health</h2></summary>
      <div class="card detail-card">${sensorHealthRows}</div>
    </details>

    <details class="section section-details" id="insights" open>
      <summary><h2 class="section-title">Today's insights</h2></summary>
      <div class="insights">${insightCards || '<article class="card">No Insights logged today.</article>'}</div>
    </details>

    <pre id="raw-report" class="raw-report">${escapeHtml(reportText)}</pre>
  </main>

  <script>
    // Loading the freshly generated report marks the snapshot as consumed.
    // The _hpvc value identifies this deliberate report opening, so the webhook
    // is sent only once even if the same page is refreshed in this tab.
    (() => {
      const openedUrl = new URL(window.location.href);
      const openingId = openedUrl.searchParams.get('_hpvc') || 'direct';
      const resetKey = 'hpvc-report-viewed-' + openingId;
      if (sessionStorage.getItem(resetKey)) return;
      sessionStorage.setItem(resetKey, '1');

      fetch('/api/webhook/hpvc_report_viewed_130', {
        method: 'POST',
        cache: 'no-store',
        keepalive: true
      }).then(response => {
        if (!response.ok) {
          throw new Error('Report-view reset failed with HTTP ' + response.status);
        }
      }).catch(() => {
        // Allow one retry after a network or HTTP failure on the next refresh.
        sessionStorage.removeItem(resetKey);
      });
    })();

    const button = document.getElementById('download-report');
    const status = document.getElementById('copy-status');
    const rawReport = document.getElementById('raw-report');

    button.addEventListener('click', () => {
      const text = rawReport.textContent || '';
      const blob = new Blob([text], {
        type: 'text/plain;charset=utf-8'
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      const now = new Date();
      const stamp =
        String(now.getDate()).padStart(2, '0') +
        String(now.getMonth() + 1).padStart(2, '0') +
        now.getFullYear() +
        '-' +
        String(now.getHours()).padStart(2, '0') +
        String(now.getMinutes()).padStart(2, '0') +
        String(now.getSeconds()).padStart(2, '0');

      link.href = url;
      link.download = 'hpvc-report-' + stamp + '.txt';
      document.body.appendChild(link);
      link.click();
      link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      status.textContent = 'Downloaded';
    });
  </script>
</body>
</html>`;

msg.payload = reportHtml;
return msg;

const value = msg.payload;
if (typeof value === 'number') {
    msg.payload = { code: value };
} else if (value && Number.isFinite(Number(value.code))) {
    msg.payload = { code: Number(value.code) };
} else {
    msg.payload = { code: 1 };
}
return msg;

const now = Date.now();
const startedAt = Number(flow.get('hpvcReportGenerationStartedAt'));
const lockIsFresh = Number.isFinite(startedAt) && now - startedAt < 120000;

if (lockIsFresh) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'generation already active' });
    return null;
}

flow.set('hpvcReportGenerationStartedAt', now);
node.status({ fill: 'blue', shape: 'dot', text: 'generation locked' });
return msg;
